-- Forever (Classic 1.60): русские страницы книг и записок. Тексты, которых не было, взяты из других баз сервера, где тот же
-- английский текст уже переведён (WotLK, Classic, Legion), и переведены вручную. Меняет только пустые значения. Можно запускать повторно.

ON DUPLICATE KEY UPDATE `Text` = IF(`Text` IS NULL OR `Text` = '', VALUES(`Text`), `Text`);
