INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(66, 'ruRU', 'однажды он вернется к своей жене и детям.\r\n\r\nНаконец, Морган вернулся домой, но все изменилось с тех пор, как он здесь был. Когда-то зеленый лес был заражен и населен нежитью и монстрами. Везде стояли разрушенные дома и фермы, и большую часть округи занимало кладбище возле Вороньего Холма. Пораженный и сбитый с толку, Морган пришел к своему дому и увидел одни развалины. Не зная, что случилось с его родными местами, он', 0),
(67, 'ruRU', 'отправился в деревню в поиске ответов и жены с детьми.\r\n\r\nМорган спрашивал о судьбе своей семьи, но никто ничего не знал. Жрец из Темнолесья, как теперь называлась деревня, посоветовал ему пойти на кладбище у Вороньего Холма и поискать там. Морган отказывался верить в то, что его семья погибла, и продолжал поиски среди ферм и домов Сумеречного леса, но тщетно.\r\n\r\nМорган отправился из Темнолесья в соседнее Приозерье, надеясь, что его семья осела там. По пути', 0),
(68, 'ruRU', 'он все-таки решил зайти на кладбище Вороньего Холма. Морган несколько часов бродил среди могил. Многие имена на надгробиях были ему знакомы, и чувство отчаяния захлестывало его все больше и больше. И вдруг он увидел маленький неухоженный участок с тремя небольшими надгробиями. Ужас обуял его, когда он подошел поближе. Морган смахнул пыль с самого большого надгробия, чтобы прочесть имя. На камне были высечены буквы, которые сложились в', 0),
(70, 'ruRU', 'трех служителей кладбища. Когда они попытались его успокоить, он перенес свой гнев на них и, обвинив их во всех своих несчастьях, убил всех троих.\r\n\r\nПозже Морган пришел в себя и увидел свой меч в груди одного из служащих. Осознание произошедшего привело его в отчаяние – он выхватил из ножен кинжал и вонзил его в свое сердце.\r\n\r\nТело Моргана Ладимора и тела трех его жертв были найдены', 0),
(71, 'ruRU', 'на следующий день. Его быстро похоронили, без обряда, в спешно выкопанной могиле на окраине кладбища. Из-за того, что Морган убил невинных, что противоречило его убеждениям, а также из-за горя, которое он испытал, так как не смог спасти свою семью, Морган не смог уйти в мир иной и остался в этом мире в облике неупокоенного мертвеца.\r\n\r\nЧерез несколько дней его могила была обнаружена пустой, тело так и не было найдено. Существо, в которое превратился Морган, бродит', 0),
(340, 'ruRU', '<HTML>\r\n<BODY>\r\n<H1>Призыв на службу в Орду</H1>\r\n<BR></BR>\r\n<P>Этот человек показал невероятные достижения силы и навыка во имя Орды. Его следует немедленно назначить на работу в Перекресток.</P>\r\n<BR></BR>\r\n<BR></BR>\r\n<P>С глубоким почтением,</P>\r\n<BR></BR>\r\n<BR></BR>\r\n<BR></BR>\r\n<BR></BR>\r\n<P>Мне кажется, неплохо.<BR></BR>\r\n- Такрин Торитель Путей</P>\r\n</BODY>\r\n</HTML>', 0),
(386, 'ruRU', 'Здесь следует отметить, что податель этого донесения оказал решающую роль не только в успехе нашей миссии, но и в поражении Ивара Мерзкого, спасении Эрланда и доставке этого донесения. Мы выражаем свою благодарность и рекомендуем командованию отметить этого человека наградами, достойными такого доблестного поведения, проявленного в полевых условиях. -Ловец Смерти Рейн Йорик, руководитель миссии', 0),
(627, 'ruRU', 'Опустошительная Вторая война против орочьей орды оставила Альянс Лордерона в потрясении и беспорядке. Кровожадные орки, которых возглавлял могущественный вождь, Оргрим Молот Рока, не только силой проложили себе путь через дворфийские земли Каз Модана, но и стерли с лица земли множество центральных провинций Лордерона. Жестокие орки разграбили даже\nотдаленное эльфийское королевство Кель''Талас, прежде чем их разрушительный поход был остановлен.', 0),
(628, 'ruRU', 'Армии Альянса под предводительством сэра Андуина Лотара, Утера Светоносного и адмирала Даэлина Праудмура отбросили орков к югу, в разоренные земли Азерота – первого королевства, павшего под яростным напором орков.\nСилам Альянса под командованием сэра Лотара удалось оттеснить кланы, которыми предводительствовал Молот Рока, из Лордерона обратно в подконтрольные оркам области Азерота. Войска Лотара окружили вулканическую орочью цитадель – Пик Черной горы – и осадили ее.', 0),
(631, 'ruRU', 'Потрепанным и обескровленным оркам оставалось лишь спешно сбежать в последний оплот орочьей силы – в Темный портал.\nТуралион и его воины гнались за остатками войска орков по зловонному Болоту Печали в мрачные Выжженные земли, где стояли Темный портал. Там, у подножия колоссального портала, обессиленная Орда и измотанный Альянс схлестнулись в схватке – той, что должна была стать последней, самой кровавой битвой Второй войны.', 0),
(1312, 'ruRU', 'Пребывание в брюхе великана способствует размышлению.\r\n\r\nПока мое тело кристаллизовалось, я пришел к выводу, что, возможно, в этом мире достаточно героев. Если я как-нибудь отсюда выберусь, я здорово врежу этому орку по призрачной шее!\r\n\r\n-Уинден Шей', 0),
(1710, 'ruRU', 'Привет, Фелнок! Мои исследования в Пылающих степях продвигаются великолепно. И я многим обязан $N за всю $gего:её; помощь! Вот что мне нужно для продолжения: Стальная спиральная бамперная кнутовина 17-калибровочный ледяной разводной ключ 12 фунтов утиных перьев Банка того клея, который ты делаешь Большое спасибо, Фелнок, и когда мы снова увидимся, напомни мне не насыпать уголь в твои сапоги! -Тинки', 0),
(1751, 'ruRU', 'Останки гигантского красного дракона были обнаружены в Болотине вскоре после Битвы за Грим Батол. Тираннистрас, по слухам, был старшим консортом Королевы Драконов, Алекстразы.', 0),
(1773, 'ruRU', 'Во все времена демонические существа пытались проникнуть в мир Титанов из Круговерти Пустоты, и Пантеон выбрал своего самого великого, Саргераса, чтобы он охранял границы миров. Благородный гигант из расплавленной бронзы, Саргерас выполнял свои обязательства несчетное количество тысячелетий, находя и уничтожая демонов везде, где возможно. Спустя века Саргерас столкнулся с двумя мощными демоническими расами, которые были помешаны на получении силы и господства над физической вселенной.', 0),
(1775, 'ruRU', 'Несмотря на то что практически бесконечной силы Саргераса с избытком хватало, чтобы победить зловещих эредаров, он был весьма обеспокоен разрушением и всепоглощающим злом, распространяемыми этими созданиями. Неспособный понять такую развращенность, великий титан начал погружаться в отчаяние. Несмотря на свою растущую тревогу, Саргерас все же избавил вселенную от колдунов, заманив их в ловушку в Круговерти Пустоты.', 0),
(1776, 'ruRU', 'Все более снедаемый тревогой и тоской, Саргерас был вынужден по приказу титанов вступить в бой с еще одной группой тварей, жаждавшей разрушения: Натрезим. Эти темная раса демонов-вампиров (также известных как повелители ужаса) завоевала множество населенных миров, вселяясь в их обитателей и склоняя их ко тьме.', 0),
(1782, 'ruRU', 'В своей ярости Саргерас разрушил темницы, в которых были заперты эредары и Натрезим, и выпустил отвратительных демонов на свободу. Эти коварные существа склонились пред необъятным гневом темного титана и предложили служить ему всеми доступными им злокозненными способами. Из рядов могучих эредаров Саргерас выбрал двух предводителей, которых поставил во главе своей демонической армии разрушения.', 0),
(1875, 'ruRU', 'Когда натиск армии троллей был сломлен и они попытались сбежать, армия Торадина начала преследование, беспощадно убивая всех троллей, которых удалось настичь. Тролли так никогда и не оправились от этого поражения, а в истории больше не будет единого народа троллей. Убежденные в том, что Кель''Талас спасен от разрушения, эльфы поклялись в верности и дружбе Аратору и семье его короля Торадина. Люди и эльфы с тех пор были в мирных отношениях.', 0),
(1965, 'ruRU', 'За изгнанным кланом Северного Волка через портал последовали лишь несколько кланов. Орки быстро развернули базу в Черных Топях, темной болотистой местности на востоке королевства Штормград. Начав исследовать новую территорию, они тут же столкнулись с защитниками Штормграда.', 0),
(1972, 'ruRU', 'Его старый друг Дуротан, вернувшийся из изгнания, напомнил ему о предательстве Гул''дана. По приказу мстительного Гул''дана Дуротан и вся его семья были убиты, в живых оставили лишь его юного сына. Но Молот Рока не знал о том, что сын Дуротана попал в плен к Адэласу Блэкмуру, одному из командиров армии людей, и стал его рабом. \r\n\r\nИменно этому юному орку суждено было стать величайшим вождем в истории своего народа.', 0),
(2004, 'ruRU', 'Орки оказались неспособны завоевать мир для Пылающего Легиона, и Кил''джеден был вынужден создать новую армию, чтобы сеять хаос в королевствах Азерота. Эта армия не должна была пасть жертвой глупой вражды, подобно Орде. Она должна была быть беспощадной и преданной своему повелителю. В этот раз Кил''джеден не мог позволить себе потерпеть поражение.', 0),
(2211, 'ruRU', 'Здесь покоится Громмаш Адский Крик, вождь клана Песни Войны\nПроклятие нашего народа началось с Грома – и им же закончилось.\nНа нашем древнем языке его имя означает "Сердце великана". Он заслужил его, вступив в поединок с демоном Манноротом\nи купив нам свободу ценой собственной крови.\nЛок''тар огар, старший брат. Да пребудет вечно клан Песни Войны. \n-Тралл, Вождь Орды', 0),
(2385, 'ruRU', 'Судьба Дейвила Легкого Горна\r\n\r\nДейвил Легкий Горн погиб в битве за Дарроушир, но его храбрость вдохновляла воинов Альянса до самого окончания войны.\r\n\r\nНаписанный им манускрипт паладина был найден армией Алого ордена. Теперь она хранится в ратуше Дольного Очага, где воины Алых черпают из нее силу и мудрость Дейвила.', 0),
(2515, 'ruRU', 'По приказу палача Зуганда ниже перечислено то, что необходимо для пополнения запасов Брилла:\n\n12 длинных мечей\n9 кинжалов\n8 круглых щитов\n15 топоров\n1000 стрел\n\nВыполнение этого заказа считается прямым приказом Темной Госпожи; ответственные будут представлены Ее вниманию, как и все, кто воспротивится Ее воле или помешает ей.', 0),
(2807, 'ruRU', 'День 1\r\nНаше странствие закончено. Мы наконец-то дошли до Силитуса, где и свяжемся с ними. Мы пришли сюда из самых разных мест, чтобы сообща свершить великое дело.\r\n\r\nВоздух весь наполнен предвкушениями. Завтра мы целиком посвятим себя строительству сооружения, которое позволит нам общаться с НИМИ.\r\n\r\nЗавтра мы будем возводить ветровой камень!', 0),
(2808, 'ruRU', 'День 2\r\nМы долго спорили о том, где следует возводить Ветровой Камень. Даже мудрейшие из нас не могут сказать наверняка, что за место описано в древнем пророчестве.\r\n\r\nЯ примкнул к тем, кто считает, что строить надо на севере, и время несомненно докажет нашу правоту. Доводы, что энергетические линии якобы пересекаются там под плохим углом, наивны и глупы. \r\n\r\nМы уже собираем с великой поспешностью все, что нужно для строительства.', 0),
(2809, 'ruRU', 'День 15\r\nНаше упорство себя оправдало. Мы первыми завершили установку Ветрового Камня. Останься с нами другие глупцы, на это ушло бы меньше недели!\r\n\r\nЗавтра мы приступим к ритуалам призыва самого Барона Казума. Он потребовал, чтобы его вызвали первым, и перечить ему мы не можем, поскольку в гневе он скор на расправу.\r\n\r\nЯ надеюсь, что он будет очень нами доволен.', 0),
(2810, 'ruRU', 'Для немедленного распространения среди всех членов Сумеречного Молота.\r\n\r\nПоиски предателя Ортелла продвигаются наилучшим образом. Наши разведчики узнали, что он скрывается в лабиринте пещер Западного Края.\r\n\r\nПредательство Ортелла прощать нельзя, а его побег ставит под угрозу всю нашу организацию.\r\n\r\nЛюбой, кто станет утаивать сведения о местонахождении Ортелла, будет должным образом наказан.\r\n\r\n-Эверан Сумеречный Владыка', 0),
(2820, 'ruRU', 'Как узнать, что они любят нас?\r\n\r\nНекоторым непонятно, как могут Древние Боги и их приспешники любить нас. Не они ли нас убивают? Не они ли причиняют всем нам боль и страдания? Разве есть в сердцах таких жестоких существ место любви?\r\n\r\nОтвет на эти вопросы очень прост. Так прост, что его излишне даже произносить.', 0),
(2821, 'ruRU', 'Вера. Вера – вот наш неиссякаемый источник радости порабощения. Вера согреет нас в самые холодные ночи Силитуса. Вера дарует нам благодать Господ, когда настанут Последние Дни.\r\n\r\nВера спасет нас.', 0),
(2822, 'ruRU', 'Ты не можешь понять ни единого слова в этой бухгалтерской книге. Ты даже не знаешь, на каком языке она написана!', 0),
(2823, 'ruRU', 'Тысячи лет назад изгнанные Высокородные приплыли к берегам Лордерона и основали заколдованное королевство Кель''Талас. Эти высшие эльфы, как они себя называли, создали источник огромной магической энергии в самом сердце своей земли — Солнечный Колодец. С течением времени они всё больше зависели от неустойчивой энергии Колодца — несмотря на горькие уроки, усвоенные в прошлые эпохи.', 0),
(2824, 'ruRU', 'Во время Третьей войны злодей принц Артас вторгся в Кель''Талас и превратил некогда могучее королевство в руины и пепел. Его армия нежити уничтожила почти девяносто процентов населения высших эльфов. Кроме того, он использовал энергию Солнечного Колодца, чтобы воскресить Кел''тузада — могущественного лича-нежить — тем самым осквернив мистические воды Колодца. Немногие выжившие эльфы, осознав, что были отрезаны от источника своей магической силы, становились всё более нестабильными и отчаянными.', 0),
(2825, 'ruRU', 'В самый тёмный час эльфов явился Кель''тас Солнечный Скиталец — последний из королевской линии Кель''Таласа. Кель, как его обычно называли, знал, что остатки его народа не протянут долго без питающей магии, которая когда-то давала им силу. Переименовав свой народ в эльфов крови в честь павших соотечественников, он научил их использовать окружающую мистическую энергию — даже демоническую — чтобы утолить их страшную жажду магии.', 0),
(2826, 'ruRU', 'В поисках новой судьбы для своего народа — теперь называемого на эльфийском наречии Син''дорей — Кель''тас отправился в отдалённый мир Запределья, где встретил падшего ночного эльфа Иллидана. Под наставничеством Иллидана Кель и его эльфы крови вернули себе большую часть прежней силы.', 0),
(2827, 'ruRU', 'К сожалению, практика эльфов крови по использованию демонической энергии привела к тому, что их бывшие соратники по Альянсу стали их избегать. Так, оставшиеся на Азероте эльфы крови с надеждой смотрят на Орду, чтобы та помогла им добраться до Запределья, где они смогут объединиться с Кель''тасом и достичь золотой судьбы, которую он им обещал.', 0),
(2871, 'ruRU', '<HTML><BODY><H1 align="center">ЛОРД ВАЛТАЛАК, продолжение...</H1><BR/><P align="left">Разделив амулет на части, мы бежали от только что восставшего призрака Валталака, а также от его армии призрачных убийц. А шум, который мы устроили, сражаясь за амулет, поднял на ноги немалое число оставшихся защитников Шпиля!</P><BR/><P align="left">Почти все мы смогли выбраться из Чёрной горы и думали, что в безопасности. Но даже оттуда, из-за грани, Валталак посылал своих прислужников за нами, где бы мы ни прятались. Вскоре после той миссии Сокрытый Клинок распался, и тогда мы стали совсем лёгкой добычей.</P><BR/><P align="left">Как ты, должно быть, уже знаешь, это делает обиталище лорда Валталака, ныне покой Зверя в Шпиле Чёрной горы, последним из населённых призраками мест.</P><BR/></BODY></HTML>', 0),
(2909, 'ruRU', '\r\nДиатор,\r\n\r\nНадеюсь, это письмо все-таки достигнет тебя. Эти демоны невероятно глупы. Они способны думать лишь о своих когтях, хлыстах и шипах на головах, которыми они то и дело норовят что-нибудь проткнуть. И я не мог положиться на инферналов, иначе бы письмо сгорело.\r\n\r\nКак я скучаю по тем временам, когда мы использовали орков! У них была хоть капля мозгов, и они могли подчиняться приказам. Быть может, нам удастся завладеть несколькими местными рабами?', 0),
(2919, 'ruRU', 'Мой слуга,\r\n\r\nВсе эти годы подготовки пошли насмарку. Дренеи вместе со своим проклятым вождем снова ушли от Повелителя! Еще и захватив с собой МОЙ корабль, который они разбили на Азероте! \r\n\r\nШпионка Повелителя – одна из эредаров – потерпела неудачу, но ей удалось передать нам местоположение Экзодара. К счастью, дренеи пока не знают, кто она такая. Так что она еще может нам пригодиться.', 0),
(2920, 'ruRU', 'Свяжись с нашим шпионом и приготовься к полномасштабному нападению на дренеев. Уничтожь их и верни мой корабль. Только ты можешь отомстить этим негодяям за ущерб, нанесенный Экзодару.\r\n\r\nНе подведи меня, гном. Если позволишь своей страсти к сокровищам взять верх над тобой, будешь жалеть об этом всю оставшуюся жизнь. Но если ты подведешь меня, она все равно будет недолгой, и ты будешь молить меня о смерти.\r\n\r\n-Король Солнечный Скиталец', 0),
(2936, 'ruRU', 'Вы нашли святилище! Осмотрев его, вы начинаете чувствовать присутствие таинственной силы, окутывающей остров. Вам становится не по себе…$B$BНа стене вы видите бронзовую табличку с надписью:$B$B"Это святилище Дат''Ремара, дань уважения благороднейшему из эльфов. Пусть всякий, кто придет сюда, вспомнит о жертве, которую он принес в борьбе с Плетью, а также о его беззаветной преданности нашему народу. Процветание Кель''Таласа – его заслуга".', 0),
(2938, 'ruRU', 'Немало времени прошло, прежде чем поборник потерял сознание. Даже он не выдержал этих пыток. Его мучитель (мне сказали, что его звали Матис) пытался вернуть его к жизни, разбрызгивая по его измученному телу разведенный в воде яд. Но Саруан не шевелился.', 0),
(2988, 'ruRU', 'Эта странная, ни на что не похожая вещь, видимо, является специально разработанным устройством.\nСудя по внешнему виду, ей уже кто-то воспользовался.\nА судя по количеству трупов вокруг, ее предназначение далеко не мирное.', 0),
(2999, 'ruRU', 'Антонивич,\r\n\r\nСначала хочу сказать, что <твой/твоя> <новый/новая> <помощник/помощница> <имя> успешно <справился/справилась> со своим заданием. Я завладел <его/ее> телом и сейчас пишу <его/ее> рукой. Это меня так забавляет – надеюсь, что когда-нибудь мне удастся завладеть и тобой, о грозный аптекарь!\r\n\r\nДокладываю, как ты мне приказал: в Цитадели Адского Пламени обитает демон, сильнее которого я никогда не встречал. Думаю, что Маннорот, властитель преисподней времен Третьей Войны, обладал такой же силой, но таких, как он, очень мало. Однако мне кажется, что этот демон заточен здесь. Меня не удивит, если окажется, что он действует против воли или находится под контролем еще более могучей силы.\r\n\r\nВремя покажет.', 0),
(3032, 'ruRU', 'Гарн!\r\n\r\nДумаю, важность твоей миссии у тебя сомнений не вызывает. Ты должен защитить драгоценный груз любой ценой. Как я и обещал, в случае успеха тебя ждет щедрая награда.\r\n\r\nПусть твои "товарищи" держат язык за зубами, а ты приглядывай за командой, и тогда все пройдет как по маслу. Когда все выполнишь, сообщи мне.', 0),
(3034, 'ruRU', 'Тетур – одно из самых опасных существ, которых мне доводилось видеть. Одного столкновения с этой тварью мне хватило, чтобы не желать повторной встречи, мне чудом удалось уцелеть!$b$bВ ту ночь была страшная буря. Свет маяка Терамора был едва различим сквозь бушующие волны и проливной дождь. Мы делали все возможное, чтобы направить корабль к маяку. И вдруг прямо перед нами из волн вырвалось это чудище!', 0),
(3036, 'ruRU', 'Чудовище раскрыло свою пасть, окатывая нас потоками ледяной воды. Его челюсти сомкнулись и оторвали нос нашего корабля. Моряки и весь груз оказались за бортом, а остатки корабля скрылись в морской пучине.$b$bПоследнее, что я помню, – это как меня выбросило из корабля в бушующее море… В моих глазах потемнело, и я решил, что сделал свой последний вздох. Когда меня привели в чувство в лазарете Терамора, мне стало ясно, что мой долг – поведать миру эту историю.', 0),
(3038, 'ruRU', 'На боку этого ящика вырезаны зловещие руны...', 0),
(3054, 'ruRU', 'Легенды о роге неистовства стихий давным-давно ходили среди таунка. Поколения героев выросли на этих преданиях, и, возмужав, отправлялись на его поиски младые сыны, но тщетны были их усилия. Был среди них и отважный воин Штормовое Копыто, что отринул семью и родной край ради погони за мечтой.\r\n\r\nСражаясь со стужей и яростными элементалями Ледяного Клинка, Штормовое Копыто в одиночку покорил неприступную гору, где на вершине ждал его сам Северный Ветер. Зная, что повелитель бурь не отдаст рог без боя, могучий рыцарь бросил ему вызов.', 0),
(3055, 'ruRU', 'Пять дней без передышки Штормовое Копыто сражался с ветром. И вот, на закате шестого дня, он наконец изгнал его с Вершины Ледяного Клинка. Теперь рог принадлежал ему! Израненный и усталый, Штормовое Копыто отправился в обратный путь.\r\n\r\nНо Северный Ветер не собирался сдаваться. Он призвал к себе армию младших элементалей и напал на Штормовое Копыто, когда тот уже приближался к родному дому. Утомленный долгой битвой воин не смог оказать достойного сопротивления и пал жертвой мести Северного Ветра, который отобрал у него рог и разломал его на две части. Из этих обломков он сделал две блестящие безделушки и подарил их своим верным союзникам, могущественным вождям горлоков.\r\n\r\n<На этом месте текст обрывается, но под ним кто-то – возможно, сам укротитель ветров Барах – сделал следующее дополнение:>\r\n\r\nПо повелению Северного Ветра великие горлоки передавали эти реликвии из поколения в поколения, от отца к сыну. И в настоящий момент обломки рога хранятся у вождя Бурблгубля и вождя Гурглбугля.', 0),
(3067, 'ruRU', 'Горамош!\r\n\r\nЯ послал к тебе представителя Эфириума. Этот посол Дейхен утверждает, что наши идеи весьма популярны среди его народа, и многие из них хотят помочь нашему делу. Выясни, так ли это, и может ли он быть нам полезен.\r\n\r\nЕсли от него будет толк, я позволю прочим представителям его народа примкнуть к нам.\r\n\r\nНе будь идиотом, сожги письмо после прочтения!\r\n\r\nM', 0),
(3068, 'ruRU', 'Лок''тар огар! Победа или смерть – вот девиз, который объединяет меня с Ордой, ибо это самая фундаментальная и непреложная истина для любого воина.\r\n\r\nЯ с гордостью отдам за вождя свою кровь до последней капли. Я – инструмент в руках вождя, его верное оружие.\r\n\r\nС этого мига и до самой смерти я живу и умру – за Орду!', 0),
(3069, 'ruRU', '$N!\r\n\r\nЕсли ты читаешь это письмо, значит, с тобой все в порядке – во всяком случае, с твоим зрением.\r\n\r\nПрошу прощения за секретность, но Агмар установил жесткий контроль за корреспонденцией – слишком уж много тут развелось воров и шпионов, как ясно следует из плакатов "Разыскивается". А я хотел обсудить с тобой крайне деликатные вопросы, которые могли бы быть неверно истолкованы новыми стражниками. \r\n\r\nДля солдата Орды потеря – это все. Потеря – это смерть, и ее не избежит никто из нас. Мы можем только надеяться, что покинем мир с честью и достоинством.', 0),
(3070, 'ruRU', 'Но победа... Победа многозначна. Как ты уже $gсам мог:сама могла, убедиться, Кор''крон набрал полную силу. Вождь отправил свой элитный отряд воинов, чтобы обеспечить нашу победу в Нордсколе. Вместе с тобой и другими героями они теснят Короля-лича и его войска к неизбежной пропасти поражения. С каждым убитым тобой противником мы еще на шаг приближаемся к достижению нашей цели – избавить мир от Артаса и Плети. \r\n\r\nНо здесь кроется сложная дилемма. Видишь ли, наши войска в Нордсколе возглавляет молодой Адский Крик, и его победы воодушевляют войска Орды по всему Азероту.', 0),
(3071, 'ruRU', 'К несчастью, Адский Крик действует слишком грубо. Хотя каждая выигранная битва оправдывает его методы, она так же подводит его все ближе и ближе к тому месту, куда не ступала наша нога уже многие десятки лет: к средоточию тьмы.\r\n\r\nЯ послал своего сына принять командование нашими войсками у Врат Гнева. Я знаю, что он будет сражаться достойно, и храню в сердце надежду на то, что его смелость не останется незамеченной среди наших войск. Он – моя душа и мой меч, разящий врагов в тех краях, где я быть не могу...Ты же будешь моими глазами и ушами. Вместе мы добьемся победы.\r\n\r\nКровь и гром... Пусть они ознаменуют твое появление.\r\n\r\nСаурфанг', 0),
(3102, 'ruRU', 'Посвящается Королю Вариану Ринну \r\nизвестному также как Ло''гош "Призрачный волк"\r\n\r\nЕго чудесное возвращение после долгих лет ссылки и лишений зажгло пламя мужества и решимости в сердцах Альянса. \r\n\r\nМы гордо пройдем по этим проклятым землям, неся в душе его светлый облик.\r\n\r\n\r\n- Верховный лорд Болвар Фордрагон', 0),
(3109, 'ruRU', 'Папа снова поручил мне заботиться о старушке Бесс. Думаю, ему нравится смотреть, как она пытается забить меня копытами до смерти. Не моя вина, что она не любит меня так, как остальных — это было лишь раз, когда я съел яблоко, предназначенное для неё. Я даже не знаю, как она об этом узнала.', 0),
(3115, 'ruRU', 'Обращение верховного настоятеля Ландгрена. \n\nНекоторым может показаться, что в дни скорби и гнева следует отречься от всего и посвятить себя только благополучию семьи и родного дома, но чувство это ложно. Отринув факел веры, отгоняющий тьму от наших душ, сердца ваших близких очень скоро окажутся беспомощными перед отчаянием и страхом. Чувство сытости, тепла и уюта, которое можно купить за деньги, не сможет спасти вашу семью от внутренней опустошенности, которая завладеет душами, ежели те забудут о своих обязательствах перед Светом.', 0),
(3116, 'ruRU', 'Обратитесь к церкви. Трудности, возникающие от отсутствия благ насущных, только укрепят вашу душу, изгонят бесов и поднимут вас на новый уровень духовного совершенства. Не стыдитесь бурчания голодных животов, царапин от камней на босых подошвах и мурашек на озябшей коже. Гордо идите по пути Света и внимайте ему всей душой. Страдания приближают вас к золотым чертогам святости, которые открыты для тех, кто крепок духом и телом. \r\n\r\nОткажитесь от ублажения плоти и приблизьтесь к истинному пониманию Света.', 0),
(3119, 'ruRU', 'Очищайте тело трудом. Очищайте душу молитвами. Очищайте ваших врагов огнем и мечом. Не избегайте боли, ибо она – ваш союзник. Примите ее, ибо боль едина для всех, верующих и неверных. \r\n\r\nСопротивление путям Света есть признак несовершенства души, который должен быть искоренен из плоти нашего сообщества.', 0),
(3167, 'ruRU', 'Западный Нордскол – Данные воздушной топографической разведки из Ледяной Короны показывают, что сообщение с Лич-лордом Хладолютом прервано. "В последний раз Хладолюта видели за пультом управления некрополем, Талрамасом, пролетавшим над Борейской тундрой в рамках выполнения сверхсекретного задания," – докладывает офицер разведки Плети, инженер Каромон. – "Наши данные свидетельствуют о том, что его кристаллы связи целы и работают, но он... хранит гробовое молчание."', 0),
(3171, 'ruRU', 'Драконий Погост – Принц Валанар объявил об открывшейся вакансии для исключительного рыцаря смерти, которому надлежит отправиться в Драконий Погост, находящийся в центре Нордскола, и возглавить элитный отряд солдат, который окажет сопротивление роду красных драконов. "Ваше обучение практически завершено, – сказал он в недавнем обращении к войскам. – Настало время выступить против защитников смертных! Мы покажем им истинное значение названия "Драконий Погост!"', 0),
(3172, 'ruRU', 'Алекстраза, Королева красных драконов и самый могущественный враг Плети в Нордсколе, набирает собственную армию. Ходят слухи, что она готова заключить союз с родом синих драконов.', 0),
(3186, 'ruRU', 'Имя: Манч\nСтатус: Жив\nКомментарий: Злой. Полный ненависти. Справится хорошо.\n', 0),
(3218, 'ruRU', 'До меня дошло, что некоторых новых рыцарей смерти могут тревожить воспоминания об их прежних жизнях. Я прошу эти неспокойные умы больше не терзаться, ибо никто не может быть переполнен большим отвращением к своим прошлым ошибкам, чем я. И всё же в Плети я нашёл отпущение.', 0),
(3219, 'ruRU', 'В своём невежестве я был когда-то паладином, присягнувшим ненавистному Свету. Ослеплённый лжой о надежде, я оставил свою жену и двух юных дочерей дома, пока разведывал присутствие Плети в нашей округе. Наш небольшой отряд неделями искал в лесах, но все следы обрывались. Наступила зима, а мы так ничего и не узнали о враге. В отчаянии мы повернули домой.', 0),
(3220, 'ruRU', 'Подъём на последний холм открыл ужасающий вид. Деревня лежала сожжённой и изуродованной. Я побежал к нашему дому. Самодельный брус был прибит снаружи двери. Слишком обезумевший, чтобы задуматься об этом, я врезался внутрь и нашёл останки своей семьи, распростёртые у моих ног, обугленные до неузнаваемости. Я отвернулся в агонии и увидел царапины на двери, где они в панике скребли её ногтями. Самые маленькие царапины принадлежали младшей.', 0),
(3221, 'ruRU', 'Позже я узнал, что в наше отсутствие распространились слухи, что рядом с деревней прячется чумоносец. Алый Крестовый поход позаботился о том, чтобы каждого последнего жителя собрали и сожгли живьём. Какой бы немыслимой ни была их жестокость, я обнаружил, что то же самое чувство теперь зародилось в моей груди. Я жаждал выследить крестоносцев, заставить их познать ярость моего клинка.', 0),
(3222, 'ruRU', 'В конце концов меня заставили вновь собраться с остальной частью моего отряда. Я чувствовал собственное отчаяние и гнев в некоторых других, но командиры приказали нам двигаться к ближайшему оставшемуся сторожевому посту. Вскоре после наступления темноты мы услышали зловещий хохот нежити, эхом разносящийся из деревьев, и волна Плети обрушилась на нас.', 0),
(3223, 'ruRU', 'Механически я убивал их. Но на каждого павшего из холмов выползали двое новых. Мы оказались в той же волне Плети, которую сами выслеживали, только теперь мы были разбиты и неподготовлены. Мои союзники поддавались ранам и истощению. Теперь Плети было слишком много, чтобы сопротивляться.', 0),
(3224, 'ruRU', 'Когда удары сыпались на меня, я вспоминал, как играл в этих лесах со своими дочерьми. Это наполнило меня ненавистью. Зачем должны существовать такие воспоминания? Они были иллюзией, служившей лишь для того, чтобы отвлечь меня от реальности боли и разложения. Мои дочери были мёртвы, а поле захватила Плеть. Смерть — единственный настоящий конец любой смертной истории. Использование силы для защиты неизбежно ведёт к поражению. Успех достаётся лишь тем, кто использует её для иной цели...', 0),
(3225, 'ruRU', 'Тогда и там я поклялся в верности Королю-личу, вестнику победы в нашу эпоху. Он очистил меня от ненавистных человеческих чувств, что терзали меня. Я был возрождён как рыцарь смерти. Нет силы, перед которой падём я и мои собратья. Нет поражений, достаточно горьких, чтобы испытать мою ледяную решимость. Очищенный Плетью, я готов утолить свою жажду смерти по всей длине и ширине Азерота.', 0),
(3281, 'ruRU', 'Штормовое Копыто, брат вождя, собрался с силами и отправился покорять Грозовую Гряду, которыми издавна правил Северный Ветер.', 0),
(3282, 'ruRU', 'Штормовое Копыто был близок к цели. Он победил Северного Ветра в самом сердце его владений, но повелитель бурь выжил и отомстил таунка за вторжение, казнив многих из них собственными руками.', 0),
(3285, 'ruRU', '2 дек. 20 года\r\n\r\nЗима в этом году особенно суровая. Сколько одежек Наставники говорят, что скоро потеплеет, но мне что-то верится с трудом.', 0),
(3287, 'ruRU', '2 часа спустя\r\n\r\nУра! Мне только что сказали, что я буду работать с людьми, которых прислали из Андорала. Уж я-то не упущу своего шанса показать, как многому я уже научился.', 0),
(3288, 'ruRU', '6 часов спустя\r\n\r\nДела идут не так хорошо, как мне бы хотелось. Состояние фермеров значительно ухудшилось за последние несколько часов. У одного из них появились крупные фурункулы, покрывающие большую часть кожи. Я испробовал все травы и снадобья, которые только были у меня под рукой. Надеюсь, вскоре им полегчает.', 0),
(3289, 'ruRU', '10 часов спустя\r\n\r\nСитуация вышла из-под контроля. Тела пациентов буквально покрыты язвами, сочащимися желто-зеленым гноем. Большинство из них без сознания, остальные же беспрестанно жалуются на онемение и боль в суставах. Глаза подернуты белой пеленой.', 0),
(3290, 'ruRU', 'Наши попытки замедлить распространение болезни ни к чему не привели. Послушники шепчутся, будто эта зараза магическая по своей природе, но наставники быстро пресекают подобные слухи. Многие ученики, направленные работать в лазарет, отказываются выполнять свои обязанности – боятся заразиться.', 0),
(3292, 'ruRU', '13 часов спустя\r\n\r\nВеликий Свет, спаси и сохрани.\r\n\r\nУ пациентов пошла кровь из глаз и ушей. Наставники говорят, что им не прожить и часа. Мы сделали все, что смогли, но этого оказалось недостаточно для того, чтобы победить болезнь. Нам остается только облегчить их страдания. Надеюсь, их смерть хотя бы даст ответы на наши вопросы. Я буду с ними рядом до самого конца.', 0),
(3293, 'ruRU', 'Хуже того – в саду нашли тело первокурсника. Ходят слухи, будто он замерз до смерти. Не припомню, чтобы в Даларане стояли такие холода.', 0),
(3294, 'ruRU', '18 часов спустя\r\n\r\nФермеры из Андорала мертвы. Я надеялся, что они обретут покой хотя бы после смерти, но ошибался. Вскоре после того, как последний из них испустил последний вздох, произошло нечто ужасное. Их искаженные болезнью тела внезапно начали двигаться и поползли по направлению ко мне и другим магам. К счастью, среди нас был опытный наставник, который быстро оправился от шока и разобрался с ожившими мертвецами.', 0),
(3295, 'ruRU', 'Почти никто не пострадал – мертвецы успели лишь оцарапать нескольких послушников и укусить одного из них в руку, рану пришлось зашивать. Вскоре после этого за нами пришли охранники и проводили нас в комнаты. Я пытался выяснить у них, что происходит, но они как будто оглохли. Между тем, я видел в коридорах вооруженных стражей. Мы что, собираемся с кем-то сражаться', 0),
(3297, 'ruRU', '24 часа спустя\r\n\r\nЯ не спал уже сутки. Честно говоря, я умираю от усталости, но в комнате слишком холодно. Мне удалось связаться с другими послушниками, запертыми в своих комнатах. Они говорят, что в цитадели введено военное положение. Наставники обыскивают крепость в поисках некроманта, ответственного за оживление трупов зараженных фермеров.', 0),
(3298, 'ruRU', 'Со времен Кел''Тузада в Даларане не ступала нога некроманта. Надеюсь, им удастся найти и покарать того мерзавца, который повинен в этом кошмаре.', 0),
(3299, 'ruRU', '38 часов спустя\r\n\r\nКарантин сняли, и послушникам наконец-то позволили покинуть комнаты. Некроманта, оживившего трупы фермеров, так и не поймали, но наставники убеждены, что в цитадели он не появлялся.', 0),
(3300, 'ruRU', 'Мы возобновили исследования этой страшной болезни, хотя тела несчастных уже значительно разложились. Наставники обратились за помощью к леди Джайне Праудмур, которая должна прибыть в цитадель к вечеру. Говорят, она потрясающе красива. Надеюсь, ее присутствие отвлечет меня от мыслей о холоде.', 0),
(3302, 'ruRU', 'Задай вопрос магу!\r\n\r\nВ: Друзья говорят, что занятия магией не придадут мне популярности среди девушек, потому что все маги – слабые и вялые. Это правда? \r\n-Джимми Таунсенд по прозвищу "Хиляк"', 0),
(3303, 'ruRU', 'О: Не волнуйся, Джимми. Твои друзья пали жертвой стереотипов, в формировании которых повинны некоторые ленивые маги, злоупотребляющие нездоровой пищей. Ничто не мешает тебе поддерживать отличную физическую форму, и в то же самое время совершенствоваться в искусстве управления основами вселенной. Даже члены Кирин-Тор находят время в своем плотном расписании для силовых упражнений, которые, вкупе со строгой диетой, дают потрясающие результаты.\r\nА напоследок спроси себя – какая девушка сможет пройти мимо парня, владеющего искусством Превращения?', 0),
(3304, 'ruRU', 'В: Родители не одобряют мой выбор профессии. Они говорят, что волшебство опасно и может привести к зависимости от более "тяжелых" форм магии – например, демонологии. А я не хочу продавать свою душу непонятно кому!\r\n-Джозеф Винтерс\r\n\r\nО: Страхи твоих родителей абсолютно необоснованны. Наверняка они просто услышали какую-нибудь байку о волшебнике, который увлекся некромантией или поклонением демонам, но подобных случаев не было за всю историю магии. Постарайся убедить маму и папу, что им совершенно не о чем волноваться.', 0),
(3305, 'ruRU', 'В: Я лишь недавно начал изучать магию, и мои друзья постоянно издеваются надо мной. Они только и делают, что просят меня сотворить им какую-нибудь еду, питье или телепорт за два квартала. Когда уже они начнут меня бояться? \r\n-Грегори Адамс по прозвищу "Тряпка"\r\n\r\nО: Как только ты выучишь заклинание "Oгненная глыба".', 0),
(3350, 'ruRU', 'А когда, наконец, он отважился посмотреть по сторонам, дерева больше не было. На его месте стояла прекрасная ночная эльфийка. "Сработало!" – воскликнул бедняга. – "У меня получилось превратить дерево! Я стал настоящим волшебником!" \r\n\r\nНочная эльфийка растерянно оглянулась и, наконец, поняла в чем дело. "Я друид, глупышка!" – улыбнулась она. – "Мы меняем форму по своему желанию".', 0),
(3353, 'ruRU', 'Запись 1\r\n\r\nСудьба нанесла удар столь внезапно, что я даже не успел понять, откуда пришла беда. Земля содрогнулась под нашими ногами, и великий шпиль, возвышавшийся над Далараном со времен Второй войны, пошатнулся.\r\n\r\nЯ увидел лицо отца, исчезнувшее за рухнувшими лесами, и закричал от ужаса, но вопль мой так и не вырвался из перехваченного страхом горла. Но даже в тот ужасный миг я не забывал о своем магическом даре. Я хотел остановить – или хотя бы замедлить неотвратимо надвигающуюся бурю, но заклинания потеряли свою силу. Вихри демонической силой опустошили меня изнутри, отняв последнюю надежду на спасение. Мне оставалось лишь закрыть глаза и ждать конца. Но каким-то образом я остался в живых.', 0),
(3354, 'ruRU', 'Запись 2\r\n\r\nВихрь бушевал несколько часов, и каждый грозовой раскат предвещал неминуемую гибель. Я прятался под аркой, некогда обрамлявшей вид на одну из рыночных площадей города. Сколько раз я наблюдал за тем, как сестра проходит под этим сводом, неся в руках сумки с покупками? Теперь предо мной лишь пыль и груда камней.', 0),
(3355, 'ruRU', 'Запись 4\r\n\r\nЯ должен верить в Кирин-Тор. Великие маги Даларана не бросят свой народ на произвол судьбы. Что такое куча мусора для опытного волшебника? Он мог бы убрать ее одним мановением руки, открыв для меня путь к свободе. Меня спасут, и я закончу свое обучение, чтобы когда-нибудь стать одним из них.', 0),
(3356, 'ruRU', 'Запись 5\r\n\r\nЯ не знаю, что стало с моими родными и с остальными жителями. Никто не откликается на мои крики о помощи. Зачем я выжил? Сердце мое вскоре успокоится, но разум не желает примириться с действительностью.', 0),
(3357, 'ruRU', 'Запись 6\r\n\r\nТьма сгущается, и воздух становится все более разреженным. Тусклые пульсары огня, которые я призвал, чтобы написать эти строки, слепят мне глаза. Вскоре я погашу их – нельзя тратить энергию впустую. Надо сберечь ее для того, что может ждать меня в дальнейшем. Я все еще надеюсь, что эти обрывки бумаги станут моим голосом, взывающим из пропасти отчаяния – шепотом, едва различимом во мраке.', 0),
(3360, 'ruRU', 'Все школы магии зачастую пересекаются для плетения крайне могущественных заклинаний, использующих различные источники силы. Это очень опасные заклятия для начинающих, поэтому вы познакомитесь с ними только на старших курсах. \r\n\r\n	Для начала вам придется усвоить основы всех школ магии. Помните, что волшебство – это не игрушка. Не занимайтесь магией без присмотра преподавателя.', 0),
(3362, 'ruRU', 'Ограждение – это направление защитной магии и одна из наиболее важных школ для начинающего волшебника. Самое известное ограждающее заклинание – это щит маны, преобразующий чистую энергию в преграду, защищающую заклинателя от нападения. Правильно выполненный щит маны может отразить большую часть направленных на вас заклинаний, но его создание сопряжено с немалыми трудностями как для начинающих, так и для опытных магов. Для того, чтобы уверенно пользоваться даже самыми простыми версиями этого оберега, требуется несколько месяцев подготовки, поэтому большинство магов предпочитают менее надежные, но более простые в исполнении заклинания.', 0),
(3372, 'ruRU', 'Мне хотелось бы напомнить моим уважаемым ученикам, что гадальные шары – это не игрушка. Их нельзя использовать в качестве привлечения лиц противоположного пола или для гаданий за плату. Считайте это первым и последним предупреждением.', 0),
(3395, 'ruRU', 'Вот почему мы основали О.П.О.С.С.У.М. (Открытая Программа Обучения Самостоятельному Сопротивлению Увлечению Магией). Наша цель – донести до вас информацию об опасностях, связанных с изучением тайных искусств. Мы хотим показать миру, что жизнь без магии может быть гораздо ярче и привлекательней. В ней есть столько интересных занятий – например, выращивание цветов или плетение корзинок. Не правда ли, звучит заманчиво?', 0),
(3396, 'ruRU', 'К тому же, наша программа оказывает реабилитационную помощь магозависимым личностям, помогает им вернуться в общество и адаптироваться к нормальной жизни. Всего за шесть дней существования мы установили тесные связи со Жрицами Элуны и Кругом Кенария. Эти организации готовы помочь вам встать на путь исправления. Запомните – никогда не поздно научиться любить себя!', 0),
(3398, 'ruRU', 'Чувствуешь себя немного подавленным? Нужна энергия? А как насчёт море энергии? Как насчёт горячей, огненной взрывной энергии?\n\nПопробуй новый ЛАВОВЫЙ ВЗРЫВ от Пироко. Ты влюбишься в его сладкий, освежающий вкус и необработанную силу внутри. Нужен быстрый заряд бодрости? Нет проблем! ЛАВОВЫЙ ВЗРЫВ восстановит тебя, даже когда ты истощён до предела.', 0),
(3399, 'ruRU', 'Серьёзно ранен? Мы тебя прикроем! ЛАВОВЫЙ ВЗРЫВ даст тебе ту дополнительную энергию, которая нужна, чтобы найти путь к безопасности!*\nЛюбишь огонь? Задумывался когда-нибудь, как круто было бы пить жидкий огонь? Если да, тебе понравится новый ЛАВОВЫЙ ВЗРЫВ от Пироко! Познай вкус ожога!\n\n*Недавние исследования показали, что Лавовый Взрыв на самом деле может никак не помогать в заживлении ран. Есть вероятность, что Лавовый Взрыв может на самом деле вызвать обильное кровотечение из, казалось бы, случайных отверстий.', 0),
(3400, 'ruRU', 'Предупреждение: Лавовый Взрыв не для всех. Беременным женщинам, детям и женщинам, которые могут быть беременны или кормят грудью, следует проконсультироваться с врачом перед употреблением Лавового Взрыва.\n', 0),
(3401, 'ruRU', 'Возможные побочные эффекты могут включать: сухость во рту, расстройство желудка, сухость глаз, несварение, боль в спине, боль в костях и суставах, лёгкое обезображивание, внутреннее кровотечение, временное безумие, зависимость от Лавового Взрыва, зависимость от магии, пироманию, боязнь паука, светящиеся глаза, учащённое сердцебиение, лихорадку, внезапные роды, недосыпание, уязвимость к холодному железу, истерию, случайные песни, всплывающие в голове, астму, демоническую одержимость, головные боли, боли в ногах, неспособность произносить букву «р» и смерть.\n', 0),
(3402, 'ruRU', 'Осторожно: употребление нескольких Лавовых Взрывов подряд может привести к самовозгоранию.\n\nПопробуй новый ЛАВОВЫЙ ВЗРЫВ прямо сейчас!', 0),
(3415, 'ruRU', 'Вскоре они стояли на границе Даларана, намереваясь разрушить его до основания и захватить Книгу Медива, с помощью которой они планировали вернуть в этот мир демона Архимонда. \r\n\r\nВ стремлении защитить город, Антонидас выступил против Артаса и его армии ходячих мертвецов. Благодаря своему исключительному дару защитной магии он создал энергетический барьер, который уничтожал любую нежить, осмелившуюся его коснуться. Это была самая первая версия ограждающих щитов, которые используются в наши дни.', 0),
(3416, 'ruRU', 'К сожалению, всего искусства Антонидаса не хватило для того, чтобы создать непреодолимую преграду для Артаса. Бывший принц нашел способ развеять заклинание, захватил Даларан и хладнокровно убил верховного мага. В результате Кел''Тузад смог проникнуть в Аметистовую цитадель, забрать Книгу Медива и призвать Архимонда. \r\n\r\nПосле того, как армии нежити покинули город в поисках новой жертвы, Архимонд разрушил Даларан до основания и превратил магические шпили города в пыль. Так пало государство Антонидаса, оплот веры и силы, лишившееся своего предводителя.', 0),
(3417, 'ruRU', '[Эпилог]\r\n\r\nПавший в битве, но не забытый потомками, Антонидас продолжает служить примером всем живущим. Его мудрость, доблесть и достижения стали залогом выживания старого союза и оплотом грядущих побед. В нашем неспокойном мире хрупкая основа нового Альянса зиждется на горьких уроках, вынесенных нами из прошлого, и почитании величайших сынов и доблестных героев Лордерона.', 0),
(3432, 'ruRU', '8 окт.\r\n\r\nКажется, я уже писал, что мне беспокоит потенциальная угроза, исходящая от заклинаний некоторых школ магии, и сравнительно слабые ограничения на их использование. Более того, углубленное изучение этих дисциплин приводит к снижению уровня академических знаний и повышению количества несчастных случаев среди студентов.', 0),
(3433, 'ruRU', 'Недавно один из моих учеников задал мне вопрос, почему мы используем довольно ограниченные по возможностям порталы, если с помощью магии скверны можно создать в два раза более широкие и в десять раз более устойчивые телепорты. Разумеется, он еще не проходил теорию достижимого и вероятного, но его любопытство привело меня к мысли о мрачности перспектив традиционного обучения, которые уже сейчас находятся в тени зловещих разновидностей магии.', 0),
(3434, 'ruRU', 'Я делаю все возможное для того, чтобы ограничить доступ учеников к знаниям по магии скверны и некромантии, но меня по-прежнему пугает – и в то же самое время восхищает -потенциал этих направлений. Я отказываюсь верить, что мысли об их эффективности могут заглушить голос разума, который призывает нас к осторожности при работе с чем-то столь ненадежным и зловещим, не хочу даже думать о том, что в этих школах заложен ключ к магическому прогрессу. Однако, наблюдая собственными глазами их непередаваемую мощь, способную уничтожить несколько акров земли один мановением руки, я опасаюсь, что мои убеждения вскоре могут пошатнуться.', 0),
(3435, 'ruRU', '16 окт.\r\n\r\nВ последнее время я полностью сосредоточился на изучении происхождения эпидемии чумы, возникшей на севере. Я отменил большую часть занятий, не желая отвлекаться от исследования этой чудовищной аномалии. \r\nПриняв беспрецедентные меры предосторожности, я доставил в лабораторию образец зараженного зерна. Простота и смертельная эффективность такого метода распространения заразы одновременно потрясла меня и ужаснула. Зачумленное зерно ничем не отличается от обычного – ни запахом, ни окраской, ни весом.\r\nВо всяком случае, теперь мне достоверно известно, каким образом чума так быстро охватила огромные территории.', 0),
(3436, 'ruRU', '17 окт.\r\nМои дальнейшие исследования привели меня к некоторым тревожным подозрениям и не менее зловещим выводам.\r\nПервичные опыты показали, что чума практически не оказывает воздействие на отличные от людей расы. Симптомы включают в себя слабость, тошноту, лихорадку, но я не зафиксировал ни одного случая смерти. Однако, на человеческий организм чума воздействует иначе, неминуемо приводя к летальному исходу.', 0),
(3437, 'ruRU', 'Было бы наивно предполагать, что столь эффективный истребитель человеческой расы случайно появился в районах, густо населенных людьми. Хотя чисто теоретически такое совпадение возможно, я принял решение бросить все силы на дальнейшее расследование причин возникновения эпидемии, ибо я беспокоюсь, что за этой чумой может стоять чья-то злая воля. \r\n\r\nОднако, мои изыскания в Даларане подошли к концу. Я должен решить, кто займется исследованиями на месте возникновения чумы.', 0),
(3438, 'ruRU', '18 окт.\r\n\r\nЯ натолкнулся на ключевой фактор распространения чумы – столь тщательно скрытый в самой ее сути, что мне пришлось отбросить последние сомнения в том, что эта эпидемия была вызвана с единственной целью – истребить все человечество. Теперь я уверен в том, что за ее распространением стоит некий изощренный в своей жестокости разум. \r\nОказалось, что смерть не является последней стадией заболевания, чума приводит к последующему воскрешению мертвого тела и превращению его в нежить. Изначально этот эффект наблюдался достаточно редко, в связи с чем я счел его незначительным побочным действием, но с течением времени тенденция сохранилась, что натолкнуло меня на ужасающую мысль: что если трупы были предназначены для выполнения какой-то миссии?', 0),
(3439, 'ruRU', 'В тот момент у меня не было никаких подтверждений этой версии, но я продолжил изыскания в этом направлении. Мне пришлось воспользоваться своими незначительными познаниями в некромантии, чтобы прочитать несколько простых заклинаний над трупом. В тот момент я не намеревался воскрешать несчастного покойника – мне всего лишь хотелось измерить поток энергии, исходивший от мертвеца. Представьте мое удивление, когда покойник внезапно ожил и набросился на меня!', 0),
(3440, 'ruRU', 'Я, не раздумывая, испепелил его на месте, о чем не раз пожалел в дальнейшем. Но теперь у меня были доказательства того, что трупы жертв чумы действительно ожидали момента, чтобы быть пробужденными чей-то зловещей волей. Очевидно, что в какой-то момент погибшие люди должны были восстать из своих могил, повинуясь велению некоего бесспорно великого некроманта.\r\n\r\n Отныне у меня не осталось сомнений в том, что эта чума – магическая по своей природе.', 0),
(3441, 'ruRU', '20 окт.\r\n\r\nЯ решил поручить расследование причин возникновения чумы моей самой талантливой ученице, Джайне Праудмур. Учитывая результаты моих исследований, только она сможет справиться с теми препятствиями, которые могут возникнуть на пути к истине. Она заберет с собой копию этого дневника и прочие документы, связанные с изучением чумы. Разумеется, я намереваюсь их опубликовать. Люди должны знать правду о надвигающейся угрозе.', 0),
(3442, 'ruRU', 'Признаться, мне хотелось бы самому заняться дальнейшими исследованиями, но Теренас остается предсказуемо глух к моим просьбам. Мне необходимо убедить его ввести карантин на севере – это наиболее важная задача, стоящая перед нами на настоящий момент. В любом случае, я полностью доверяю мудрости Джайны. Если она не сможет довести это расследование до конца, то ее уже никто не заменит.\r\n\r\n-Антонидас-\r\n<Запечатано знаком Совета Шести>', 0),
(3444, 'ruRU', 'Почему это произошло? Прежде всего, из-за того, что силовые линии не растут на деревьях. Чрезмерное использование одного луча изнашивает его структуру по всему Азероту. Поэтому мы устанавливаем фиксированную плату за использование порталов – эти деньги идут на замену оборудования, но все равно не могут покрыть все затраты по ремонту линии.', 0),
(3445, 'ruRU', 'Помните, что лучше всего окупаются массовые порталы, ибо на перемещение нескольких людей требуется меньше ресурсов силовой линии, чем на создание нового портала. В настоящий момент готовится к одобрению проект программы "Общий портал", которая будет предоставлять налоговые льготы для магов, создающих порталы не меньше, чем для пяти человек. Подробнее об этом законопроекте читайте в последнем выпуске "Вестника Кирин-Тора".', 0),
(3446, 'ruRU', 'Правильно созданный портал не менее надежен, чем путешествие на дирижабле (а возможно, даже более, учитывая инженерные способности отдельных гоблинов), но нарушение техники безопасности при работе с порталами может привести к серьезным последствиям. Предлагаем вашему вниманию список правил по телепортации:', 0),
(3447, 'ruRU', 'Правило #1: Не прокладывайте портал за пределы зоны высадки Кирин-Тора. Наибольшая опасность заклинания телепортации заключается в его потенциале. Мы понимаем, насколько велико искушение открыть дверь в любую точку пространства, и поэтому вынуждены назначить крайнюю меру наказания для ограждения магов от подобных действий. \r\nСвободный доступ к открытию порталов имеют владельцы особых прав D-6, но их выдача строго ограничена. Для получения подобной лицензии обратитесь к мастеру порталов вашего города.', 0),
(3448, 'ruRU', 'Правило #2: Создавайте портал в отведенном для этого месте и соблюдайте технику безопасности при его использовании. Не открывайте портал под ногами людей. Не задерживайтесь при прохождении портала. Не используйте портал в качестве мусоропровода или щита. Не создавайте портал в качестве защиты от дождя и прочих стихийных явлений.', 0),
(3449, 'ruRU', 'При прохождении портала не высовывайтесь назад и не пытайтесь схватиться за его внутренние или внешние края. Границы портала – это не поручни, и их разрушение может привести к несчастным случаям.', 0),
(3450, 'ruRU', 'Правило #3: Не пытайтесь хитростью или силой заставить другого человека пройти через портал. Это, во-первых, опасно, а во-вторых, пагубно влияет на вашу репутацию. (см правило #2).', 0),
(3451, 'ruRU', 'Правило #4: К использованию порталов не допускаются лица, сменившие форму, ибо это может привести к взрыву. Подробнее об этом читайте в брошюре "Правила использования заклинания превращения".', 0),
(3452, 'ruRU', 'Правило #5: Не исключайте фильтр воды из структуры заклинания. Матрица порталов не пропускает через себя большое количество текущей воды, и поэтому их можно использовать даже под водой. Если вы хотите провести через портал элементаля воды, опустите компонент фильтра, но не забудьте включить его при создании подводного портала! Дабы показать, к каким последствиям могут привести подобные ошибки, мы вынуждены порекомендовать вам к прочтению параграф из "Реестра происшествий средней тяжести" под номером 34-з: "Великий потоп в Приозерье и наводнение в Стальгорне, 24 г. НЭ".', 0),
(3453, 'ruRU', 'Правило #6: Стандартные размеры портала – 3 ярда, 1 фут, 3 и 3/4 дюйма в высоту, 2 ярда, 8 футов, 9 и 15/16 дюйма в ширину. Для создания портала двойной ширины требуется получение лицензии Г-16, которая выдается только после 8 лет использования обычных порталов. Для получения подобной лицензии обратитесь к мастеру порталов вашего города.\r\n\r\n<В инструкции еще несколько сотен страниц.>', 0),
(3456, 'ruRU', 'Правило #2: Пользуйтесь стандартным перечнем существ, рекомендованных для превращения. Многие маги выбирают в качестве объекта превращения экзотических тварей, но, чтобы снизить выплаты по страховым полисам, Кирин-Тор вынужден ограничить список рекомендованных для превращения существ. Наиболее подходящая форма для всех случаев – это овца (полный список приведен на страницах последнего выпуска "Вестника Кирин-Тор". Превращение в слизнюков, эфириалов, силитидов и драконов строжайше запрещено и карается по закону".', 0),
(3458, 'ruRU', 'Правило #4: Не превращайте слабых существ в более могущественных. Хотя это кажется очевидным, мы вынуждены порекомендовать вам к прочтению параграф из "Реестра происшествий средней тяжести" под номером 8761-e, "Маг Джон Квинт: сожжен больным оленем, превращенным в ожесточенного оплавленного великана."', 0),
(3460, 'ruRU', 'Правило #6: Не превращайте недвижимые объекты! Хотя мы с трудом можем поверить своим глазам, но результат подобного эксперимента рекомендуется к прочтению в новом выпуске "Реестра тяжких происшествий" под номером 1-a, "Пол-царства за коня или сто одна причина, почему не следует превращать государство в лошадь". \r\n<В инструкции еще несколько сотен страниц.>', 0),
(3472, 'ruRU', 'Докладная записка верховному магу Ансирему Руноплету', 0),
(3473, 'ruRU', 'Я прошу вас не толковать превратно мою попытку пролить свет на эту ситуацию, но господин Арголи более не является студентом нашего учебного заведения. Недавно верховный маг Атаерик ускорил подготовку своих учеников, в результате чего я получил целый курс неопытных болванов, которые с трудом способны создать стакан воды! Но если у остальных все еще есть шанс со временем превратиться в достойных магов, то подготовка вышеупомянутого студента не выдерживала никакой критики. Он не был способен выполнить даже простейшего поручения.', 0),
(3474, 'ruRU', 'Известно, что из трав Альтерка получается отличная ароматическая добавка к чаю. Я отправил этого юношу за стены парящего города, чтобы тот собрал мне немного свежих растений, и совершенно не обратил внимания его затянувшееся отсутствие, ибо был занят ремонтом двухсотлетнего гобелена, который был подожжен другим тупоголовым студентом.', 0),
(3475, 'ruRU', 'Сейчас я вспоминаю глупую ухмылку Арголи при получении данного задания, и понимаю, что совершил ошибку, отправив его с этим поручением. Тайна исчезновения студента была раскрыта сегодня утром, когда я отправил вниз моего посыльного за важной запиской, которую я уронил, задумавшись возле окна. Посыльная вернулась с печальным известием о том, что внизу на скалах были обнаружены останки Арголи.', 0),
(3476, 'ruRU', 'Когда же я нашел сложенный пучок сквернопли среди его одеяний, у меня отпали последние сомнения в том, что несчастный сам повинен в своей гибели. Очевидно, он буквально воспринял мой призыв "раздобыть немного травы" и пожевал немного сквернопли перед тем, как отправляться на задание. Об остальном вы можете догадаться сами.', 0),
(3478, 'ruRU', 'Слушайте меня!\r\n\r\nМагия – это не то, чему вас учили. Исходящая от нее опасность гораздо выше, чем польза! Но у вас еще есть шанс спастись! Познайте пути природы, придите в равновесие с окружающим миром, пока у вас еще есть такая возможность.\r\n\r\n<Эту листовку украшает какая-то неизвестная печать.>', 0),
(3482, 'ruRU', 'Милая Реанна!\r\n\r\nКаждая секунда, проведенная вдали от тебя, кажется вечностью. Знала бы ты, как мне хочется вновь ощутить прикосновение твоей ласковой, мохнатой руки.\r\n\r\nДаже если звезды упадут с небес – я не стану их подбирать, ибо давно уже ослеплен сиянием твоих глаз.', 0),
(3483, 'ruRU', 'Милая Реанна!\r\n\r\nЛуна все убывает, и я с трудом могу дождаться новолуния, что укроет нас от всего мира под покровом темноты.\r\n\r\nЯ живу и дышу лишь надеждой на новую встречу с тобой.', 0),
(3484, 'ruRU', 'Милая Реанна!\r\n\r\nВот и настал долгожданный вечер, но только холодный ветер сопровождает меня в этот печальный час. Безмолвные ветви деревьев склонились над рощей, где некогда мы провели столько упоительных часов, и их жесткие листья хлещут меня по лицу, будто наказывая за глупость.\r\n\r\nЯ умираю от желания снова увидеть тебя...', 0),
(3485, 'ruRU', 'Милая Реанна!\r\n\r\nПредставь себе мое удивление, когда почтальон отказался передавать тебе мое письмо! Должно быть, это какая-то ошибка! Я просматриваю копии всех моих предыдущих посланий, но не вижу в них ничего такого, что могло оскорбить твои чувства. Знай же, что я сам доставлю тебе это письмо, раз уж этот проклятый дурак убежден в том, что любовь всей моей жизни не желает больше ничего обо мне слышать!', 0),
(3486, 'ruRU', 'Уважаемый господин!\r\n\r\nСпешу уведомить вас о том, что леди Реанна высказала свое категорическое нежелание в дальнейшем получать от вас корреспонденцию. Таким образом вам рекомендуется воздержаться от написания писем по ее адресу.\r\n\r\nМиледи также просила вам передать, что инцидент с вашим неожиданным превращением был, безусловно, забавным, но она не желает повторения ничего подобного.', 0),
(3487, 'ruRU', 'Гид по ресторанам Даларана\r\nВскоре после того, как Инзи открыл свой ресторан "Благодарность за отвагу", в городе воцарились тишина и покой. Местные и приезжие выстраиваются в очередь, чтобы забыть о распрях и ссорах за кружечкой пива и ломтем свежеиспеченного хлеба. Этот ресторан славится низкими ценами, изобилием свободных мест и разнообразием спиртных напитков со всего мира. В такой атмосфере нетрудно представить себя утомленным подвигами героем! Что бы вы ни заказали – оставьте в желудке место для медового карибу!', 0),
(3506, 'ruRU', 'Запись 1. Прежде всего, позвольте представиться. Я – верховный маг Варгот, предводитель первой экспедиции Кирин-Тора на Дренор. Мы сопровождали силы Альянса через Темный Портал, и ныне разбили наш основной лагерь – Кирин''Вар – в Фаралоне, неподалеку от исторической родины орков клана Веселого черепа. Это очень уютное место!', 0),
(3507, 'ruRU', 'Запись 42. Мы продолжаем разработку силовых линий, и результаты нас вполне устраивают. С удивлением обнаружили совпадения в структуре лучей Азерота и Дренора, что, возможно, свидетельствует о сходных направлениях эволюции этих миров.\r\nМой напарник Набериус доложил, что клан Веселого Черепа заключил перемирие с силами Альянса. Лично я оркам не доверяю, так что подобный союз может обернуться как благом, так и бедствием.', 0),
(3508, 'ruRU', 'Запись 205. Большая часть войск Альянса вернулась на Азерот. Надеюсь, наш подробный отчет, переданный с генералом Туралионом, благополучно достигнет Даларана.\r\nБеспечно воздвигнутые порталы Нер''зула рвут Фаралон на части, и его зеленые холмы медленно тонут в Круговерти пустоты. Мне надо найти путь обратно!', 0),
(3509, 'ruRU', 'Запись 1363. Настал 14 год, и Кирин''Вар все еще держит оборону. Раз в день мы собираемся на обед, который наколдовывает Люминрат, а волшебный клинок Датрика охраняет деревню от незваных гостей. В разрушении Дренора обнаружились некоторые положительные стороны, ибо последовавшие за этим магические процессы оказались чрезвычайно интересными для изучения!', 0),
(3510, 'ruRU', 'Запись 1969. \r\n<Эта поспешно накарябанная заметка разительно отличается от предыдущих записей, сделанных каллиграфическим почерком.>\r\n\r\nНа нас напали! Это солдаты Кель''таса, их тысячи!!!\r\nЯ вижу летающие корабли, превосходящие по размерам самые большие дирижабли, повсюду чувствуется чужеродная магическая энергия, взрываются мана-бомбы.\r\nЯ успел оградить башню силовым щитом... не знаю, что случилось с остальными...\r\n\r\n<запись обрывается>', 0),
(3511, 'ruRU', 'Запись 1970. Войска Келя застали нас врасплох, в результате чего я оказался запертым в башне Кирин''Вар. Внизу дверь охраняет магический голем, запрограммированный на атаку любого живого существа. Теперь я могу проштудировать все книги башни – но никогда не смогу ее покинуть!\r\nХотя мания Келя не дает мне связаться с Равандиром, я чувствую, что мой ученик все еще жив.', 0),
(3512, 'ruRU', 'Альманах старого волшебника: Альянс $n Многие маги полагают, что Кирин-Тору, как историческому союзнику Альянса, нет необходимости изучать входящие в него расы. Мне кажется, что мы должны придерживаться противоположного мнения: прийти к пониманию других народов можно только через их познание. – С.В.', 0),
(3513, 'ruRU', 'Люди: одна из наиболее гибких и легко приспосабливаемых рас, среди представителей котрой встречаются крайне одаренные маги. Любой список самых могущественных заклинателей Азерота возглавляют именно люди. Наиболее эффектным примером тому является автор сего альманаха, который тоже принадлежит к человеческой расе. $n Дворфы: обладают средним магическим потенциалом и практически не владеют высшими заклинаниями. Хотя многие из них предпочитают обучаться мудрости жрецов, некоторые представители добиваются успеха на поприще тайных знаний и некромантии.', 0),
(3514, 'ruRU', 'Гномы: исключительно одаренные чародеи. Понемногу они завоевывают репутацию самых могущественных магов мира и всегда имели представителей в совете Кирин-Тора.$n Ночные эльфы: хотя они избегают пользоваться тайными знаниями, считая их прерогативой Плети, среди этой расы встречаются величайшие друиды всех времен.', 0),
(3515, 'ruRU', 'Дренеи: эта древняя раса значительно усилила Альянс своими могущественными волшебниками и искусными почитателями Света. Впрочем, многие дренеи обратились к искусству шаманизма после прибытия в Калимдор.$n Высшие эльфы: магия этой расы необычайно сильна. Они буквально одержимы жаждой знаний в этой области, и по своей учености превосходят даже людей. Жрецы высших эльфов особенно отличились во время войны при Хиджале.', 0),
(3516, 'ruRU', 'Альманах старого волшебника: Орда.$n Вплоть до последнего времени наши сведения об Орде были отрывочными и зачастую не соответствовали тому, что мне приходилось наблюдать, сражаясь с представителями этого союза. Однако, поскольку в последнее время Кирин-Тор занимает нейтральное положение по отношению к действиям Альянса и Орды, нам удалось расширить наши познания о представителях последней. – С. В.', 0),
(3517, 'ruRU', 'Орки: несмотря на обилие физической силы, представители этой расы обладают вполне неплохими магическими способностями. Среди них мало хороших заклинателей, но исторически они склонны к шаманизму с примесью темных искусств – чернокнижия и некромантии.$n Таурены: некоторые экспериментируют с тайными искусствами, но большинство этих быкоподобных людей тесно связаны с магией земли, предпочитая следовать учениям шаманов. Кроме того, опытные друиды тауренов значительно превосходят по силе многих верховных магов Дарнаса.', 0),
(3518, 'ruRU', 'Тролли: проявляют неожиданно высокие способности к магическим искусствам, что удивительно, учитывая их историю и чудовищную репутацию. Во время путешествия по тролльским империям – Зул''Аману, Зул''Фарраку и Зул''Драку – я обнаружил среди населения множество заклинателей: от шаманов и жрецов тени до странных почитателей звериного обличья, чем-то напоминающих наших друидов. $n Нежить: обладает такими же магическими способностями, как и при жизни... а порой даже большими. К примеру, Отрекшиеся маги Сильваны владеют потрясающими магическими навыками и с легкостью пускают их в ход во время битвы.', 0),
(3519, 'ruRU', 'Эльфы крови: историческая связь с магической энергией оставила несмываемый след на всей расе эльфов крови. Эти изящные, зависимые от магии существа преуспевают в любой школе волшебства и даже научились следовать близкому к паладинству пути рыцарей крови.$n Таунка: очень похожи на своих собратьев-тауренов в плане приверженности природной магии.', 0),
(3520, 'ruRU', 'Альманах старого волшебника: прочие способные к магии расы.$n Магия доступна не только расам Орды и Альянса. Многие существа, населяющие Азерот, проявляют волшебные способности. – С.В.', 0),
(3521, 'ruRU', 'Наги: хотя мужские особи больше полагаются на оружие, женщины-наги являются превосходными волшебницами, повелевающими стихиями воды и льда. Следует отметить, что их древняя королева Азшара по праву считается одним из лучших заклинателей в истории Азерота.$n Нерубы: изначально среди них магической силой владели только предводители, но после нападения Плети многие зачумленные нерубы стали последователями некромантии.', 0),
(3522, 'ruRU', 'Огры: большинство из этих беженцев Дренора избрали путь воина или следопыта, но некоторые предпочитают развивать в себе дар волшебства. Один из первых огров-магов, Чо''галл, был заклинателем огромной силы (не говоря уже про силу физическую).$n Сатиры: эти опасные существа чем-то напоминают ночных эльфов с искаженными демоническими телами и столь же ужасающими познаниями в магии. Рекомендуется по возможности не вступать с ними в контакт.', 0),
(3523, 'ruRU', 'Синие драконы: древние дети Малигоса считаются экспертами в тайной магии. Некоторые из них – например, отважный Калесгос – дружелюбно относятся к смертным волшебникам и с готовностью помогают им в изысканиях. К несчастью, последние сведения с севера свидетельствуют о том, что некоторые синие драконы стали проявлять враждебность к заклинателям. Нам пока не известны причины столь резких перемен.', 0),
(3524, 'ruRU', 'Альманах Старого Волшебника: шаманы.$n В ходе странствий мне часто приходилось встречаться с племенами, практикующими шаманизм. Многие из этих народов живут тем, что выращивают на своих землях, предпочитая поклонение природе техническому прогрессу. – С.В.', 0),
(3525, 'ruRU', 'Свинобразы: оставшиеся в Калимдоре представители этого племени практикуют геомантию – грубую разновидность шаманизма. Некоторые зараженные чумой свинобразы остаются приверженцами этой формы магии даже после превращения в нежить.$n Гноллы: крайне необычная раса. Однажды мне удалось простейшим фокусом завевать расположение вождя племени. Правда, через день он забыл про этой и натравил на меня своих охотников. В любом случае, гноллы обладают некоторым сродством к природному шаманизму, но слишком нетерпеливы, чтобы этим заниматься.', 0),
(3526, 'ruRU', 'Кентавры: женские особи практикуют некоторую форму извращенного, темного шаманизма, но мужчины-кентавры крайне редко прибегают к магии. $n Волчеры: эти волкоподобные твари могут показаться примитивными особями – но только на первый взгляд. Их предводители – крайне одаренные шаманы.', 0),
(3527, 'ruRU', 'Оракулы: несмотря на то, что являются заклятыми врагами волчеров, они имеют очень схожий общественный строй. Воины выполняют всю черную работу, а предводители практикуют весьма могущественные формы шаманизма. $n Фурболги: в настоящее время среди них крайне редко встречаются шаманы – это искусство более распространено среди свободнорожденных племен. Более того, такие фурболги даже способны на смену формы, подобно опытным друидам.', 0),
(3528, 'ruRU', 'Альманах Старого Волшебника: последователи природной магии $n Природная магия не ограничивается только шаманизмом. Многие примитивные расы Азерота могут накладывать чары, черпая энергию из сил земли, но это еще не причисляет их к шаманам. В Аметистовой цитадели по сей день ведутся споры об источнике подобной магии. – С.В.', 0),
(3529, 'ruRU', 'Клыкарры: эти моржеподобные люди пользуются магией, чрезвычайно схожей с шаманизмом, но наши исследователи по сей день не смогли определить ее источник.$n Кобольды: эти примитивные существа способны лишь на простейшие магические действия. Изредка мне приходилось видеть особей, могущих создать довольно большие огненные шары, но в остальном они не представляют опасности для опытного заклинателя.', 0),
(3530, 'ruRU', 'Дикие совухи: к этим существам я причисляю лунных совухов, совунов и совиных медведей. Эти очаровательные великаны владеют природной магией друидов, схожей с той, что практикуют ночные эльфы.$n Гарпии: злобные женщины-птицы, владеющие мощной стихийной магией. Нам ничего не известно об источнике их силы, поскольку они 1) крайне агрессивны 2) выкрикивают заклинания на неизвестном каркающем языке 3) ужасно воняют.', 0),
(3531, 'ruRU', 'Мурлоки: долгие годы считалось, что эти загадочные существа способны лишь на самую элементарную магию, однако нам не стоит обманываться их примитивным обликом. Рыбоподобные люди владеют крайне могущественными заклинаниями школы воды и земли, и их количество с каждым днем все увеличивается. $n Макруры: люди-лобстеры, от природы наделенные даром повелевать стихией воды.', 0),
(3532, 'ruRU', 'Альманах старого волшебника: существа, не владеющие магией.$n Волшебство подвластно далеко не всем. Многие тысячелетия примитивные твари этот мира прекрасно обходились без магии, компенсируя ее ловкостью и силой. Некоторые расы намеренно избегают пользоваться магией по различным убеждениям, но совету Кирин-Тора необходимо понимать, что движет этими существами. – С.В.', 0),
(3533, 'ruRU', 'Гоблины: недоверчиво относятся к магии, предпочитая ее техническому прогрессу. В отличие от своих вечных конкурентов – гномов у них отсутствует магический дар и понимание тайных искусств. Однако некоторые гоблины все же умудряются объединять магические силы с техникой, добиваясь потрясающих результатов. $n Трогги: этим примитивным тварям попросту недостает интеллекта для владения магией.', 0),
(3534, 'ruRU', 'Магнатавры: громадные существа, полностью лишенные способностей к магии. Среди них крайне редко встречаются заклинатели – разумеется, предпочитающие шаманистические формы заклинаний. Однако я хочу заметить, что магнатавры крайне агрессивны, и их плотные шкуры способны выдержать целый поток ледяных стрел.$n Врайкулы: хотя эти полугиганты с северного континента практически незнакомы с магией, они учатся некромантии по повелению Короля-лича. Также ходят слухи о некоей рунической магии врайкулов, но мне так и не удалось подтвердить их или опровергнуть.', 0),
(3542, 'ruRU', 'Верховному магу Антонидасу, Великому волхву Кирин-Тора\nВеликий город Даларан обязан жизнью величайшему и мудрейшему из своих сынов.\nДруг мой, твоя жертва была не напрасной.\nС любовью и уважением,\nДжайна Праудмур', 0),
(3544, 'ruRU', 'Ты нашёл обломки загадочного объекта. За пламенем можно разобрать знак «M:1815212085». Интересно, из какого мира этот объект...', 0),
(3550, 'ruRU', '<HTML>\r\n<BODY>\r\n<P>Здесь содержится подробная информация о местонахождении тайных точек обмена посылками в Лок Модане. Если в ваши руки попадут какие-либо документы Лиги исследователей или их союзников, поместите их в одном из этих тайников, и наш посыльный заберет их в течение недели и доставит на операционную базу.</P>\r\n<BR/>\r\n<P>Запомнив все местонахождения, немедленно сожгите книгу, чтобы противник не смог ей завладеть ни в коем случае. Если по каким-то причинам вам покажется, что враги подозревают вас, тотчас же сожгите книгу. Ни при каких обстоятельствах она не должна попасть в чужие руки, иначе это неминуемо приведет к разоблачению наших путей сообщения.</P>\r\n<BR/>\r\n<P>За Рагнароса!</P>\r\n<BR/></BODY>\r\n</HTML>', 0),
(3551, 'ruRU', '<HTML>\r\n<BODY>\r\n<H1 align="center">Место 1: западный причал Лока</H1>\r\n<BR/>\r\n<P>К северо-востоку от Телсамара есть небольшое поселение с причалом, которым иногда пользуются дворфы во время рыболовного сезона. Донесение нужно положить в водонепроницаемый ящик в укромном месте под причалом.</P>\r\n<BR/>\r\n<P>Отправлять и забирать донесения следует только ночью, чтобы не попасться на глаза местным рыбакам. По понятным причинам этим тайником не стоит пользоваться часто во время сезона рыбной ловли.</P>\r\n</BODY>\r\n</HTML>', 0),
(3552, 'ruRU', '<HTML>\r\n<BODY>\r\n<H1 align="center">Место 2: пещера Седых Лап</H1>\r\n<BR/>\r\n<P>К югу от Телсамара есть большой холм. На южном склоне холма можно заметить тропинку, ведущую к пещере на вершине. Донесение нужно спрятать за камнями в глубине пещеры.</P>\r\n<BR/>\r\n<P>Пожалуйста, воздержитесь от частого использования этой пещеры в качестве укрытия и/или убежища. Использование пещеры таким образом ставит под угрозу сохранность донесений и секретность передвижения нашего курьера.</P>\r\n</BODY>\r\n</HTML>', 0),
(3553, 'ruRU', '<HTML>\r\n<BODY>\r\n<H1 align="center">Место 3: Логово Шанды</H1>\r\n<BR/>\r\n<P>В скале к юго-западу от места раскопок есть небольшая пещера, в которой когда-то жил одинокий отшельник. Там поселилась Шанда, поэтому поблизости больше никто не живет. Вход в пещеру – отличное место для документов.</P>\r\n<BR/>\r\n<P>Напомню: Шанда – это огромный паук-убийца, размером вдвое больше дворфа. Не оставляй документы в самой пещере, если даже Шанды там не будет. Она там появится, это лишь вопрос времени.</P>\r\n</BODY>\r\n</HTML>', 0),
(3554, 'ruRU', '<HTML>\r\n<BODY>\r\n<H1 align="center">Место 4: Каморка на раскопках Сталекрута</H1>\r\n<BR/>\r\n<P>В самом центре раскопок Сталекрута есть скрытая от посторонних глаз каморка. Это отличное место для тайника – прямо под носом у Лиги исследователей.</P>\r\n<BR/>\r\n<P>Трогги отвлекли внимание Лиги исследователей, но нельзя забывать, что они враждебны нам. Так что ведите себя здесь ночью поосторожнее. Трогги могут устроить засаду.</P>\r\n</BODY>\r\n</HTML>', 0),
(3555, 'ruRU', '<HTML>\r\n<BODY>\r\n<H1 align="center">Место 5: Идол-череп Мо''граша</H1>\r\n<BR/>\r\n<P>Этот каменный идол в форме черепа похож на те, что встречаются в поселениях огров, но он находится немного южнее тех мест, где обычно живут огры. Положите донесение к его основанию.</P>\r\n<BR/>\r\n<P>НЕ кладите донесения В РОТ черепа. Так уже были навсегда утеряны несколько документов и одна рука.</P>\r\n</BODY>\r\n</HTML>', 0),
(3556, 'ruRU', '<HTML>\r\n<BODY>\r\n<H1 align="center">Место 6: Роща на месте бывшего озера Лок</H1>\r\n<BR/>\r\n<P>Небольшая рощица молодых деревьев в центре озера Лок – отличное место для тайника.</P>\r\n<BR/>\r\n<P>Когда озеро Лок высохло, это место стало более доступным, но зато там обосновались кроколиски.</P>\r\n</BODY>\r\n</HTML>', 0),
(3561, 'ruRU', '<Записи аптекаря напоминают бессмысленные каракули – наряду со сложными алхимическими формулами в них полно рисунков, похожих на детские. Вы ухитряетесь прочитать часть последних записей.>\r\n\r\n...очень сильная скверна, гнездящаяся в глубине живых тканей. Она очень заразна, когда <несколько слов нельзя разобрать из-за кляксы> по пищевой цепочке. Сегодняшние опыты показали, что она имеет лишь частично биологическую природу. Грязное Копыто, мой <неразборчиво> компаньон, охвачен жаждой мести и не хочет видеть других, более конструктивных применений своей <оставшаяся часть предложения заляпана чем-то зеленым>. Исследования продвигаются медленно. Надеюсь, у моих товарищей в Алталаксе дела идут лучше.', 0),
(3581, 'ruRU', '"Ролевая игра"\n\nХорошие навыки ролевой игры жизненно необходимы. Ни одна гениальная гномиха не хочет гигантского занудства. Очаруй её рассказами о твоих будущих межконтинентальных приключениях:\n\n  "Ты и я, детка, мы полетим в Калимдор, вырежем наши имена на боку Тельдрассила и проведём остаток жизни, качаясь на ветках в кратере Ун''горо."\n\n"Рассказывание историй"\n\nПоделись историями о вашем захватывающем совместном будущем! Чем неправдоподобнее, тем лучше. Ничто не возбуждает гномиху так, как амбициозный план. Это также отличный повод для разговора!\n\n  "Объединив наши блестящие умы, мы могли бы вернуть Гномреган. ... а почему мы вообще до сих пор не вернули Гномреган?"', 0),
(3582, 'ruRU', '"Поддразнивание"\n\nПоддразнивание — искусство шутливо высмеивать женщину. Будь осторожен, легко можно перейти границу. Назвав её "Гоблинской Гэнк-мошкой", ты пойдёшь домой, нося тот Зелёный Гордокский Эль, который ты только что купил. Попробуй что-нибудь более тонкое. \n\nЕсли она ведёт себя по-детски и не прекращает прыгать по столам в середине бара, попробуй:\n\n"Слышал, в приюте Штормграда открылась вакансия звёздного артиста."\n\nЕсли она не перестаёт болтать о себе, игриво попробуй:\n\n"А где у тебя кнопка выключения?"\n\nВАЖНОЕ ЗАМЕЧАНИЕ: у гномих НЕТ кнопки выключения. Попытка её найти может привести к потере жизни, конечностей или кошелька.', 0),
(3583, 'ruRU', 'Твои вкусы более экзотичны? \nЖелаешь кого-то немного неземного? \nКопытца — это твоё, а суккубы чуть перебор?\n\nЧитай дальше, мой друг...', 0),
(3584, 'ruRU', 'Я только сошёл с корабля на Лазурном берегу, когда остановил группу дамочек-дренеек в самом соку — около 230 лет. Они смеялись и прекрасно проводили время. Какая удача, ещё на причале, и я уже нашёл именно тот тип весёлых, энергичных дренейских женщин, с которыми хотел познакомиться в этой поездке. \n\nСначала немного тревожно, я глубоко вдохнул и напомнил себе: «Они тоже здесь, в Азероте, в отпуске, хотят познакомиться с новыми людьми и прекрасно провести время».\n\nИ действительно, они были в восторге увидеть одного дьявольски очаровательного гнома, такого как я, в Экзодаре. Оказалось даже, что мы оба остановились рядом с Хранилищем Света. Мы обменялись глубокими, проникновенными взглядами в глаза друг друга, пообещав встретиться снова у А''дала позже этим вечером.', 0),
(3585, 'ruRU', 'На следующий день я встретил другую красивую дренейку — блеск её рогов давал лишь намёк на её утончённый вкус. Я спросил, почему она в гостях в Экзодаре, и, к моему удивлению, она сказала, что она здесь не в гостях — она здесь живёт. \n\nСлова, которые я говорил себе раньше, вернулись в мою голову: \n\n«Она в отпуске, хочет познакомиться с удивительными людьми и прекрасно провести время».\n\nЯ всё понял неправильно, она вообще не была в отпуске! И тогда вдруг заскрипели шестерёнки моего разума: я убеждал себя, что они такие отзывчивые, потому что в отпуске. Что за гнолльская отговорка! \n\nЯ весёлый, интересный парень, с которым любая разумная девушка захочет пойти в группу, в отпуске или нет! Теперь, встречая дренеек, я напоминаю себе простую истину:\n\n«Она тоже хочет познакомиться с людьми и прекрасно провести время».', 0),
(3586, 'ruRU', 'Следующие 497 страниц этого словаря состоят целиком из странно ракурсных фотографий, сделанных на Супер Снэппер FX 2000.', 0),
(3587, 'ruRU', 'Как назначить свидание дворфийке:\n\n1. Попроси её купить тебе выпить.', 0),
(3588, 'ruRU', 'Будем честны. С конца Третьей войны девушки ночных эльфов услышали всё. На самом деле, они слышали всё это уже задолго до того, как родились мы с тобой. \n\nЕсли хочешь занять разум девушки-ночного эльфа, тебе придётся выделиться. Конечно, мы все слышали истории о девушках ночных эльфов, танцующих на почтовых ящиках и раздевающихся, чтобы заплатить за дрессировку ночной пантеры. Правда это или нет, но если хочешь заставить улыбку заиграть на губах этой прекрасной леди, тебе нужно быть уникальным, запоминающимся и уверенным в себе. \n\nНачни с того, что покажи, что ищешь больше, чем просто красотку. Конечно, она может прыгать, может танцевать, но может ли она поддержать достойный разговор? Понимает ли она вообще правильное использование самофланжа? Умеет ли она веселиться?\n\nНет ничего хуже, чем привести ночную эльфийку на вечеринку, лишь чтобы наблюдать, как она неловко стоит одна, прерывая разговор только для того, чтобы посетовать на утрату своей высокородной сестры во время Войны Древних.', 0),
(3589, 'ruRU', 'Нет ничего сравнимого с завоеванием сердца человеческой девушки. Бесконечно прощающие, безгранично заботливые и невероятно весёлые, человеческие девушки стали причиной падения бесчисленных героев на протяжении веков. (См. Главу 3: «Джайна Праудмур и мужчины, которые её любили»)\n\nОднако поколение за поколением доказывало, что для привлечения девушки своей мечты нужно нечто большее, чем деньги, внешность или эпический доспех. Даже сила гномьего изобретательства здесь не поможет. \n\nЧтобы по-настоящему очаровать сердце другого человека, тебе следует обладать этими качествами.\n\n* Быть весёлым и дружелюбным\n* Быть вызовом\n* Быть мужчиной\n\n', 0),
(3590, 'ruRU', 'Быть весёлым и дружелюбным\n\nБывал ли у тебя друг, который приходит к тебе домой и портит всем настроение? Ага. У всех был такой. Приглашают ли его снова на вечеринки? Только если он приносит эль. Если хочешь быть привлекательным человеком, живи привлекательной жизнью. \n\nТы обнаружишь, что чем больше тебе нравится общаться с другими, тем больше им нравится общаться с тобой! \n\nНет более быстрого способа испортить девушке вечер, чем нагнать на неё нужду и извинения. Отпусти это, прими веселье, и твоя уверенность взлетит.', 0),
(3591, 'ruRU', 'Быть вызовом\n\nСлишком многие гномы в наши дни ходят, опустив голову, печально шаркая от таверны к таверне, безнадёжно держась за эти ограничивающие убеждения, что ни одна человеческая девушка никогда не захочет их. Они врываются в таверну, осыпают её комплиментами и бесплатными напитками, а потом идут домой удручённые. \n\nЧто ж, позволь мне первым сказать тебе, друг: когда ты отдаёшь себя так дешёво, ты умаляешь ценность своей уникальной, изысканной личности. Общество внушило тебе, что ты не приз, что женщины никогда тебя не заметят, что ты должен умолять о любви и внимании.\n\nОни ошибаются. Не раздавай свою привязанность так свободно. Вместо вопроса «Нравлюсь ли я ей?» спроси себя: «Нравится ли она мне?» \n\nБрось ей вызов — покажи, что ищешь девушку, предлагающую больше, чем красивое лицо. Если она не может угнаться за твоей жизнью, иди дальше. Если она показывает, что у неё есть что предложить, ты в начале чего-то прекрасного.', 0),
(3592, 'ruRU', 'Быть мужчиной\n\nВ эпоху, когда нас изгнали из наших домов, заставили сражаться за само наше выживание и столкнули лицом к лицу с ужасами, невиданными прежде в Азероте, можно подумать, что природа мужественности была бы лучше понята. \n\nК сожалению, искусство мужественности было утрачено, смыто блеском и гламуром битвы. Однако не всё потеряно! С практикой и уверенностью ты можешь вновь обрести связь с собой. \n\nКогда ты встретил человеческую девушку своей мечты, и она показала себя достойной твоей привязанности:\n\n* Бери на себя инициативу — покажи ей всё прекрасное в твоём мире\n* Держи её за руку — развивай близкие, тёплые отношения\n* Проявляй уважение — к себе, к ней и к миру вокруг\n\nПревыше всего:\n\n* Будь ответственным\n', 0),
(3593, 'ruRU', 'Устранение неполадок\n\nХотя не всё всегда идёт так, как ты ожидаешь, именно это делает жизнь непредсказуемой и увлекательной. Однако есть несколько советов, которые помогут тебе значительно улучшить свою жизнь. Вот некоторые распространённые ошибки:\n\n* Не гонись\n* Не будь навязчивым\n* Не зацикливайся на той, кому ты не нравишься\n\nВсё это исходит из коренного убеждения, что тебе непременно нужна именно та женщина, с которой ты сейчас разговариваешь. Освободись — в этом прекрасном мире много женщин, и если с одной не получилось, отпусти. Ты обнаружишь, что становишься привлекательнее, чем меньше ты цепляешься.\n', 0),
(3597, 'ruRU', 'Тебе нужно встретиться с чародейкой Тибалин на верхнем этаже Серебряного анклава. Она доверит тебе книгу, которая не имеет цены. Будь осторожен в своих перемещениях и охраняй эту книгу своей жизнью. Отнеси её обратно Каладис Ясное Копьё к покою Квель''Делара со всей поспешностью.', 0),
(3598, 'ruRU', 'Тебе нужно встретиться с магистром Хаторелом внутри «Грязного зверя». Он доверит тебе книгу, которая не имеет цены. Будь осторожен в своих перемещениях и охраняй эту книгу своей жизнью. Доставь её Миралиону Солнечному Клинку к покою Квель''Делара со всей поспешностью.', 0),
(3604, 'ruRU', 'Как Отрекшиеся, мы сражаемся против Короля-лича, мы сражаемся против Альянса... иногда мы даже ссоримся с другими расами Орды. Нас мало, и мы сталкиваемся с огромными препятствиями... но мы выживем и победим.$b$bКак и товарищ-охотник, ты будешь делать это издалека, с луком в руке и животным-спутником рядом. Твоя сила исходит не из тайного волшебства или воинского мастерства, а из твоей способности жить с земли.$b$bПуть охотника лежит перед тобой. Он начинается с меня, твоего наставника. Где он заканчивается... мы пока не знаем.', 0),
(3606, 'ruRU', 'Мы едва ушли из Кезана живыми! Вулкан уничтожил все... мой дом, повозку, питомца-кабана, домик моего кабана, его повозку... \r\n\r\nНо, по крайней мере, нам удалось попасть на корабли! Мы пойдем прямо в Дуротар, а когда ступим на твердую землю, обманем парочку орков и через неделю снова будем с деньгами!', 0),
(3607, 'ruRU', 'Кажется, мы уже целую вечность в океане. Не думаю, что кто-нибудь знает, где мы находимся.\r\n\r\nНаши припасы заканчиваются, а половину воды пришлось потратить на самодельный опреснитель. Мы выкинули несколько человек за борт, чтобы увеличить скорость, но оставили все их золото, так что это мало помогло.\r\n\r\nНо все равно это было весело.', 0),
(3626, 'ruRU', '<HTML>\n<BODY>\n<BR/>\n<H1 align="center">Королева Азшара</H1>\n<BR/>\n<BR/>\n<P>Да будет эта статуя свидетельством нашей бесконечной преданности почтенной королеве Азшаре.</P>\n</BODY>\n</HTML>', 0),
(3627, 'ruRU', '<HTML>\n<BODY>\n<BR/>\n<H1 align="center">Великий следопыт Валериан</H1>\n<BR/>\n<BR/>\n<P>В память о прославленном герое Вайш''ира, великом следопыте Валериане. В своем служении он подарил красоту и спокойствие улицам нашего изысканного города. И он же пожертвовал жизнью, чтобы надолго избавить свой народ от страха и обеспечить ему жизнь без войны. О его подвигах будут помнить вечно.</P>\n</BODY>\n</HTML>', 0),
(3628, 'ruRU', '<HTML>\n<BODY>\n<BR/>\n<H1 align="center">Лестария Вайш</H1>\n<BR/>\n<BR/>\n<P>Этот памятник возведен в честь нашей возлюбленной – матриарха Лестарии Вайш. В течение сотни лет она вела жителей своего великолепного города Вайш''ир к эпохе вечного процветания. Пусть же она и ее дочь, сиятельная леди Вайш, освещают путь нашему народу и в грядущие столетия.</P>\n</BODY>\n</HTML>', 0),
(3629, 'ruRU', '<HTML>\n<BODY>\n<BR/>\n<H1 align="center">Верховная жрица Сэрален</H1>\n<BR/>\n<BR/>\n<P>Пусть эта статуя станет вечным памятником в честь верховной жрицы Сэрален за все то, что она сделала для превращения храма Кель''Дормир в сияющий маяк веры. Пусть ее новая служба у самой королевы Азшары станет свидетельством возможностей тех, кто родился в нашем любимом Вайш''ире.</P>\n</BODY>\n</HTML>', 0),
(3630, 'ruRU', 'Касым,$B$BОн вернулся.$B$B- Дозорный Махар Ба', 0),
(3632, 'ruRU', '<В письме не хватает некоторых слов, так как чернила во многих местах смыло водой.>\r\n\r\n... любая форма ... основана на ... противостоянии угнетателей и угнетенных...\r\n\r\n... нечего терять, кроме своих цепей...\r\n\r\n... прошлое не должно быть забыто...\r\n\r\n... нельзя простить...\r\n\r\n... ВОССТАНЕТ ВНОВЬ!', 0),
(3633, 'ruRU', 'Слуги, наш повелитель отдал приказ. Вы должны напасть на Сторожевой холм и освободить адмирала. Все, что удастся награбить по пути, можете оставить себе.\r\n\r\n-Хеликс', 0),
(3634, 'ruRU', 'Стоит только дать человеку плащ с гербом, и он поклянется в вечной преданности вашему делу. Теперь эти люди – просто стадо овец, которым наплевать на ваши нужды. Они носят плащи с гербом своего вождя и их волнует только то, чего желает он.\r\n\r\n-V', 0),
(3635, 'ruRU', '<HTML>\r\n<body>\r\n<h1>Зверское убийство бродяг у фермы Хмуроброва\r\n</h1>\r\n<BR/>\r\n<p>\r\nПо свидетельствам очевидцев четверо бродяг подверглись нападению, когда они несли домашние пироги к поселению на восточном берегу.\r\n</p>\r\n<BR/>\r\n<p>\r\nВот что говорит Джимб "Свечник" Макханниган, ставший свидетелем нападения: "Да-да, я все это видел собственными глазами. Это $gбыл:была:c, $c. $gОн так выглядел:Она так выглядела,, как будто что-то $gзамышлял:замышляла,. Вот, а потом $gприрезал:прирезала, этих бродяг, выкрикивая "Слава Штормграду!" да "Слава Вариану Ринну!". Думаю, что и Лу $gон потом убил:она потом убила,. Но сам-то я этого не видел, слишком страшно было, убежал."\r\n</p>\r\n</body>\r\n</HTML>', 0),
(3636, 'ruRU', 'Я с трудом могу в это поверить. Мы терпели эти мучения четыре долгих года, но скоро все кончится. Братство будет возрождено, и мы прокатимся по этой земле, словно наводнение, и очистим ее от грязи и скверны.', 0),
(3637, 'ruRU', 'Час нашего избавления близится, братья и сестры! Сегодня мы сбросим оболочку своих прежних жизней и возродимся как герои!\r\n\r\n-В', 0),
(3648, 'ruRU', 'Шаг 1: УБИТЬ\r\nШаг 4: Поспать?\r\nШаг 2: ПОЕСТЬ\r\nШаг 1: Сходить в туалет', 0),
(3649, 'ruRU', 'Вы нападете снизу!\r\nМы нападем сверху!\r\nВстретимся в центре города людишек.\r\n\r\n-Изувой, сын Изувоя', 0),
(3652, 'ruRU', 'Гноллы племени Темношкуров и орки Черной горы собирают войска, чтобы напасть на Штормград.', 0),
(3653, 'ruRU', 'Приказы братства Кровавого Паруса\r\n\r\nОбратите внимание на сказанное здесь, ребята. Это будет наша финальная атака на Пиратскую Бухту.\r\n\r\nКрасавчик в последний раз подвел меня. Тот, кто его заменил, находится на севере. Он будет командовать наступлением на суше, через этот проклятый туннель.\r\n\r\nКапитан Кильватель и "Бурун" зайдут с юго-запада, чтобы не дать пушкам обстрелять нас с мыса. Ему понадобятся люди, порох и много веревок.', 0),
(3654, 'ruRU', '"Госпожа Удача" войдет прямо в гавань и откроет огонь. Капитан корабля получит приказ никого не брать в плен – все мужчины, женщины и дети, причастные к общению с разбойниками Черноводья из Пиратской Бухты, должны быть убиты на месте.\r\n\r\nЯ буду командовать атакой с тыла вместе с "Кровавой Завесой". Мы обеспечим огневую поддержку и защиту от налетчиков, которые придут на оборону своей драгоценной Пиратской Бухты.', 0),
(3655, 'ruRU', 'Никакого плана отступления не будет, ребята. Когда мы прибудем в Пиратскую Бухту, то сожжем и захватим город – или умрем, пытаясь это сделать. Примите это к сведению.\r\n\r\n-Командир флота Фираллон', 0),
(3656, 'ruRU', 'Кишан, если ты читаешь эту записку, значит, я мертв. Скорее всего, моя позиция раскрыта.\n\nОрки творят с пленными немыслимые зверства. Да, с пленными, Кишан. У них клетки, полные военнопленных. Если собираешься взорвать эту долину, сначала придется освободить пленных.\n\nСкажи моей жене, что я ее люблю и пусть вынесет этот проклятый мусор.\n\n–Сухопек\n\nP.S. У них есть черные драконы.', 0),
(3672, 'ruRU', 'ТЮРЕМНЫЕ ЗАПИСИ КУРЦЕНА\n\nНе разглашать', 0),
(3673, 'ruRU', 'БЕРРИН БЕРНКВИЛЛ\n\nПреступления: неповиновение, нарушение порядка\n\nНаказание: заключение, 50 лет\n\n', 0),
(3674, 'ruRU', 'ЭМЕРИН ДЖУНИС\n\nПреступления: наказание по особому приказу полковника Курцена\n\nНаказание: заключение, 75 лет\n\n', 0),
(3675, 'ruRU', 'ОСБОРН ОБНОТИКУС\n\nПреступления: безумие\n\nНаказание: заключение, 130 лет', 0),
(3676, 'ruRU', 'БУКСТОН ИРОД\n\nПреступления: связь с мятежниками\n\nНаказание: смерть через повешение\n', 0),
(3677, 'ruRU', 'ПОЛКОВНИК КОНРАД КУРЦЕН\n\nПреступления: слабость\n\nНаказание: сброс с башни\n\n', 0),
(3678, 'ruRU', 'ДОСЬЕ ОФИЦЕРОВ КУРЦЕНА\n\nНе разглашать', 0),
(3679, 'ruRU', 'НАЧАЛЬНИК АНДЕРС\n\nКомандует диверсантами и бойцами джунглей. Отвечает за ополчение лагеря и защиту его ресурсов от нападений мятежников.', 0),
(3680, 'ruRU', 'НАЧАЛЬНИК ГАУЛУС\n\nКомандует знахарями и сушителями голов. Отвечает за медицинский корпус и мир с ближайшими племенами Кровавого Скальпа и Раскольников Черепов.', 0),
(3681, 'ruRU', 'НАЧАЛЬНИК МИРАНДА\n\nКомандует теневым отрядом Курцена. Отвечает за хранение голубого камня и дальнейшее изучение его свойств.', 0),
(3682, 'ruRU', 'НАЧАЛЬНИК ЭСКИВЕЛЬ\n\nВременный начальник после смерти полковника Курцена. Отвечает за надзор над всеми операциями экспедиции Курцена.', 0),
(3683, 'ruRU', 'Луна над Долиной', 0),
(3686, 'ruRU', 'Гри''лек Странник', 0),
(3689, 'ruRU', 'Падение Гурубаши', 0),
(3690, 'ruRU', 'Поднявшись из океана подобно гигантской водяной башне, Нептулон наслал на обреченный И''лалай великих краккенов. Столь огромны они были, что в них росли целые джунгли водорослей и плавали левиафаны. \r\n\r\nСамый большой краккен высоко поднял руки и обрушил их в море, посылая вперед гигантские волны. И все они устремились на И''лалай.', 0),
(3691, 'ruRU', 'Краккены взревели, как океанский шторм: \r\n\r\n"Мы идем".\r\n\r\nМин''лот, твердо держась на ногах, призвал свою магию. Волны, устремившиеся к И''лалай, разделились и обошли город с двух сторон, обрушившись на джунгли. Затем Мин''лот приказал своим ученикам начать песнь усмирения, и десятки троллей запели.\r\n\r\nИ один голос звучал громче остальных.', 0),
(3692, 'ruRU', 'Мин''лот закричал – магия собрала всю мощь заклинаний его учеников, и он обрушил ее на приближающегося краккена.\r\n\r\nМоре расступилось, и заклятие Мин''лота устремилось к слугам Нептулона. Оно обрушилось на них, и тысячи молний вскипятили воду и оставили множество кратеров в земле.\r\n\r\nМин''лот вскричал, торжествуя, он знал, что его заклинание сокрушит противников.', 0),
(3693, 'ruRU', 'Но краккены стары, очень стары. Они помнят времена, когда земля только вышла из моря.\r\n\r\nОни помнят правление Древних и пришествие свергнувших их Странников. Они помнят времена, когда магия была юной.\r\n\r\nОни стары и владеют многими тайнами. И хотя заклинание Мин''лота было сильным, все же, как и тролли, не вечным.\r\n\r\nИ его действие закончилось.', 0),
(3694, 'ruRU', 'Это не помогло связать краккенов, только их разозлило. На протяжении вечности ни один смертный не мог причинить им боли, а заклинание троллей это сделало.\r\n\r\nИ они сбросили путы заклинания Мин''лота, а потом взревели и преисполнились ярости.\r\n\r\nПослышался рокот, гигантские волны поднялись из глубин и устремились к суше. Когда они достигли И''лалай, их тень накрыла весь город.\r\n\r\nНо прежде чем его уничтожить, краккены остановились.', 0),
(3695, 'ruRU', 'Тролли-знахари содрогнулись и воззвали к своему учителю. Мин''лот смотрел на водяные валы, обреченный, но не сломленный. Он обратился к своим ученикам и прошептал несколько слов, которые затем были высечены в камне. Мин''лот повернулся к краккенам.\r\n\r\nЕго лицо исказила гримаса, и он метнул в них свой посох – это было его последнее отчаянное деяние.\r\n\r\nКраккены разгневались на Мин''лота, и океан обрушился на И''лалай.\r\n\r\nОн перестал существовать.', 0),
(3696, 'ruRU', 'И воды обрушились на джунгли, сметая все на своем пути. Тролли и животные вопили в ужасе, когда вода догоняла и поглощала их.\r\n\r\nМногие тролли Гурубаши не понимали, почему вдруг океан вышел из берегов, но потом они умерли – так ничего и не поняв.\r\n\r\nНаконец, достигнув гор, волны остановились. Успокоившись, они вновь отхлынули к берегам, оставляя после себя полосу разрушений.\r\n\r\nВода отступила, но осталась в И''лалай, поглотив его навечно.', 0),
(3697, 'ruRU', 'И вождь Вар''газул, который находился в безопасности за горами, в Зул''Гурубе, спустился в джунгли и увидел, что его народа больше нет.\r\n\r\nИ он пришел в отчаяние, так как его мечты о завоеваниях потерпели крах.\r\n\r\nА Мин''лота-Змея так и не нашли.', 0),
(3698, 'ruRU', 'Гробница Императора', 0),
(3701, 'ruRU', 'Мы высадились на землю! Точнее, разбились о нее. Лодки ночью налетели на берег, пока "капитан" занимался ерундой.\r\n\r\nМы все проснулись, лежа лицом вниз на этом таинственном песчаном пляже! Никто и понятия не имеет, где мы, но нам придется выживать в этой экзотической местности, не отмеченной ни на одной карте.\r\n\r\nЯ сказал, что все мы проснулись? Ну, это было преувеличение.', 0),
(3702, 'ruRU', 'Мы нашли нечто удивительное! Какой-то старый разбитый механизм. Один из тех собирателей древностей, которые пережили крушение, сказал, что эта штуковина – творение титанов.\r\n\r\nЧто бы это ни было, готов поспорить, она стоит денег. Ребята, которые ее нашли, сказали, что у них болели головы, и из этой штуки исходило странное сияние, но КАКАЯ РАЗНИЦА?', 0),
(3703, 'ruRU', 'Ребята, которые нашли этот артефакт, ведут себя немного СМЕШНО! Нет, ничего такого плохого с точки зрения гоблина. Они прирезали всего одного или ДВОИХ.\r\n\r\nДумаю, это не так уж и плохо! Но всем окружающим все равно НЕМНОГО смешно, ха-ха-ха.\r\nХотя этот их грубиян слишком много БОЛТАЕТ.', 0),
(3704, 'ruRU', 'Остальные позволили мне ПРИМКНУТЬ к ним наконец-то они позволили мне смотреть на АРТЕФАКТ достаточно долго и я почувствовал покалывание они сказали МОРДОФАРШ знает все он самый УМНЫЙ я надеюсь что с его помощью мы сможем ОСВОБОДИТЬ этот пляж от ДРУГИХ ЗЛЫХ ГОБЛИНОВ которые прилетели на своих ЛЕТУЧИХ МАШИНАХ чтобы УБИТЬ НАС они соврали они сказали МЫ ПРИБЫЛИ ИЗ ПРИБАМ-БАСКА ЧТОБЫ СПАСТИ ВАС но нас не обманешь мы отобрали у них все ха-ха-ха', 0),
(3705, 'ruRU', 'ВКУСНЫЙ ЖУРНАЛ НАДО ЕГО СЪЕСТЬ\r\n\r\n<Остальные страницы отсутствуют>', 0),
(3706, 'ruRU', 'Долина Североземья – опасное место, и навыки выживания, свойственные охотнику, здесь весьма пригодятся. Нечего и говорить о том, что твои успехи в деле защиты долины впечатлили меня, и я с нетерпением жду встречи. Прошу, разыщи меня у входа в аббатство.', 0),
(3707, 'ruRU', 'Ваше Святейшество, Чо''Галл дал нам новый приказ: мы должны стереть ваш собор с лица земли. Когда от духовного центра Штормграда останется лишь кратер, начнется паника и лишенные иллюзий крестьяне потянутся к нашей истинной религии. Я посылаю вам взрывчатку. Во имя Молота! Во имя Смертокрыла! Во имя великих дней, которые скоро наступят! -Самуэльсон', 0),
(3709, 'ruRU', 'Картис, Омасум!\r\n\r\nПришло время ритуала, о котором мы говорили. Я покидаю Стратхольм, чтобы заняться пленником в центральной бойне Чумного леса. Вы отвечаете за внешнюю охрану. Если вы меня подведете, то мой господин заберет ваши жизни. Если все будет в порядке, еще один брат-дворф присоединится к вам.\r\n\r\n- Анастари', 0),
(3715, 'ruRU', 'Тиффин Эллериан Ринн, \r\nкоролева Штормграда, \r\nсправедливая и беспристрастная, чья мудрость сравнится лишь с бескрайней добротой. \r\nДа озарится Свет сиянием твоей души, ибо мир становится тусклее в твое отсутствие.', 0),
(3716, 'ruRU', 'Гравиус!\n\nС сегодняшнего дня ты должен удвоить усилия. Масштаб нашего проекта только что вырос в несколько раз. Твои археологические и геологические изыскания могут подождать.\n\nОтныне ты должен копать вниз как можно быстрее. Бригады в Шлаковой яме будут вести проходку с другой стороны, чтобы соединить свои туннели с твоими. Подземная империя дворфов Черного Железа растет, Гравиус, и мы в ее авангарде.', 0),
(3717, 'ruRU', 'Справишься – будешь вознагражден. Знай, что эти приказы исходят не от меня, а от надзирателя Малтория и самого эрцгерцога.\n\nКопай глубже,\nглавный землекоп Звоноус', 0),
(3743, 'ruRU', 'Здесь покоится $N', 0),
(3745, 'ruRU', 'Зефирий, прислужник Ал''акира\r\n\r\nПроживает в развалинах казарм.', 0),
(3746, 'ruRU', 'Теракула, прислужник Теразана\r\n\r\nБродит по тропе за старыми казармами.', 0),
(3747, 'ruRU', 'Кровояд, прислужник Нептулона\r\n\r\nЗаточен в западном крыле тюрьмы.', 0),
(3748, 'ruRU', 'Инферний, прислужник Рагнароса\r\n\r\nЗаточен в восточном крыле тюрьмы.', 0),
(3749, 'ruRU', 'Д-1000\r\n\r\nПоджидает тебя на старой арене.', 0),
(4420, 'ruRU', 'Я даже не мог себе представить, что сражение окажется настолько страшным.\nПовсюду раздается грохот артиллерии Орды.\nИх снаряды дождем сыплются на палубу, и вопли команды заглушает грохот ответного огня.\nАдмирал Тейлор велел мне оставаться в укрытии, пока не кончится бой.\nСнаружи у моей двери поставили охрану.\nЯ не нахожу себе места. Я должен быть там, наверху, я должен сражаться!', 0),
(4421, 'ruRU', 'Те, кто не погиб в сражении, стали жертвами бури, пришедшей следом.\nПока наши потрепанные корабли шли сквозь дождь и туман, почти все тяжелораненые умерли.\nЯ делал все, что моих силах, чтобы помочь им, но этого оказалось недостаточно.\nПочему я никогда не успеваю спасти друзей?', 0),
(4422, 'ruRU', 'Я проснулся посреди ночи от громкого звука, похожего на гром.\nКорабль несло на скалы.\nОн накренился и затрещал, на палубе раздавались крики.\nЯ бросился к двери каюты, но мой телохранитель запер меня внутри.\nЯ ничего не могу сделать – остается только ждать.', 0),
(4423, 'ruRU', 'Флагманский корабль вынесло на незнакомый берег. Корабль неподвижен, снаружи царит полная тишина.\nЗа мной никто не пришел, боюсь, команда мертва.\nКаюта заполняется водой, так что мне скоро придется найти способ выбраться отсюда.\nЕсли кто-то из солдат Альянса найдет эту запись, знайте, что я, принц Андуин Ринн, жив.\nЯ собираюсь сойти на берег в поисках еды и в надежде на помощь.\nПрошу передать моему отцу, что со мной все в порядке."', 0),
(4456, 'ruRU', 'Век хозенов весьма недолог. Средний возраст для старейшин – двадцать лет, поэтому зрелость у хозенов весьма непродолжительна.$b$bВ отличие от сдержанных и воспитанных цзинь-юй, хозены – страстный народ, обожающий любовь, обожающий ненависть и вообще, обожающий все те чувства, на которые он только способен, до тех пор, пока эти чувства сильны.', 0),
(4457, 'ruRU', 'Хозены, обитающие в горах Кунь-Лай, – поразительно злобные существа, даже по меркам самих хозенов. В этих суровых краях зачастую не хватает пищи. В голодные времена лидеры хозенов могут объявить "набег" на ближайшие поселения .$b$bВо время набегов каждый хозен, который способен стоять на ногах, присоединяется к огромной орде, сносящей все на своем пути. Хозены в выигрыше в любом случае – либо они награбят достаточно еды, чтобы перезимовать, либо избавятся от слабых и больных, и им хватит того, что есть.$b$bВ течение многих лет шадо-паны и груммели сохраняют шаткий мир с хозенами в обмен на поставку им продовольствия. Хозены и рады бы забрать все силой, но их удерживает страх перед шадо-панами... Как правило.', 0),
(4479, 'ruRU', 'Когда небеса загудят в смятенье\nИ страх поднимется из долин,\nВместилище нашего избавленья\nРазбей до самых его глубин.\nКинжалы злые великих, статных\nТенью и деревом ты свяжи.\nЧтоб ярость бурь королей закатных\nНазло всему продолжала жить.', 0),
(4480, 'ruRU', 'Пускай обещание злата купило\nЗаклятья, что силу хранят в веках.\nСвяжи их чары, мой друг, с той силой,\nЧто душит огонь и былого страх.\nПостигнув этот рецепт священный,\nИсполни точно его совет.\nОмой плоды его Кровью Древних,\nИ война кошмаров сойдет на нет.', 0),
(4501, 'ruRU', 'Когда могу объявили о полном истреблении сауроков, несколько легионов еще оставалось на полях боя. Когда вести об измене их владык достигли ушей сауроков, они подняли оружие на своих военачальников и исчезли в землях богомолов, обойдя вражеские войска. Бесчисленные легионы могу и их рабы отправились на охоту за дезертирами. Но никто из них не вернулся.', 0),
(4502, 'ruRU', 'Сауроки, всегда сопротивляющиеся до последнего, не уступали могу ни пяди болот Красаранга. Именно здесь, на незнакомой противнику территории, у них появились шансы на победу.$b$bКоличество смертей начало расти, когда повстанцы отравили запасы воду и стали разрушать постройки могу.$b$bПоддавшись слепой ярости, император из Доцзяна все посылал и посылал в Красаранг войска, рабов и оружие, пытаясь уничтожить всех оставшихся сауроков до последнего.$b$bНо все его попытки были тщетны.', 0),
(4503, 'ruRU', 'К своим умершим соплеменникам могу относятся как к источнику запасных частей. Души помещают в камень, чтобы иметь возможность использовать их в любой момент. Плоть и кровь помогают продлевать жизнь тех, кто верен императору. Если могу хоронят в неприкосновенности – это признак великого уважения.$b$bПеред вами Долина Императоров, место упокоения сотен поколений военачальников, королей и императоров, некогда правивших этой землей.$b$bРискните разорить эти могилы!', 0),
(4504, 'ruRU', 'Даже с точки зрения могу правление императора Доцзяна II было кратким и кровавым. Его маниакальное стремление завершить дело своего отца и навсегда освободить империю от легионов бунтующих сауроков заставило его оставить двор и начать военную кампанию, обреченную на провал.$b$bОбозревая с высоких скал Красарангские джунгли, он смотрел, как медленно вырубаются заросли, как строится Подземелье Доцзянь и как гибнет раса сауроков.$b$bНо чего он не ожидал, так это того, что остатки пятого и седьмого легионов сауроков взберутся на огромнейшие скалы под покровом ночи, отрежут императорский шатер от Долины Четырех Ветров и столкнут в пропасть. Тело Доцзяна так и не нашли, а хаос, воцарившийся в столице, привел к тому, что почти два года в империи правила смута. Сауроки, тем временем, растворились в пустошах, не оставив и следа...', 0),
(4505, 'ruRU', 'В течение многих веков могу использовали плоть как оружие, деформируя и изменяя ее по своей черной воле. Но после неудачи с сотворением расы сауроков могу начали искать возможность создать новое оружие, на сей раз – полностью подвластное им.$b$bДревние исследования научили их обращать плоть в камень и наоборот. Безжизненный камень можно было оживить, наделить волей (или безволием) и заключить в нем душу.$b$bЭти мрачные ритуалы породили рожденных-из-камня, нефритовых солдат, которых магия сотворила из субстанции жизни пленников могу. Эти создания были сильны, ужасны обликом и, что важнее всего, хранили непоколебимую верность своим хозяевам.', 0),
(4509, 'ruRU', 'Этот древний алтарь цзинь-юй может пролить свет на происхождение этой расы. Мы видим изображение примитивных приземистых водяных существ. Их окружают озера на золотом поле; возможно, они олицетворяют Вечноцветущий дол. $b$bОдно из примитивных существ держит над водой посох, но символы вокруг его головы вам незнакомы. Возможно, этот язык древнее династии могу.$b$bТочная связь между  древними водными существами и долом остается покрыта тайной.', 0),
(4510, 'ruRU', 'Иерархия цзинь-юй представляет собой строгое кастовое общество, доказательством чему служит эта каменная таблица с перечисленными на ней именами. Яйца отсортировываются в соответствии с нуждами общества.$b$bМногие цзинь-юй принадлежат к касте рабочих и усердно трудятся на строительстве дамб и иных сооружений. Других назначают ремесленниками, и они оправляются на обучение сразу после появления на свет.$b$bЛучшее жилище и больше всего еды достается воинам и жрецам, и лишь наиболее успешные священнослужители могут стать старейшинами или Говорящими с водой. Браки между представителями разных каст находятся под запретом.', 0),
(4511, 'ruRU', '$p,$b$bтвои друзья выжили в сражении с Ша Сомнения, и за ними ухаживают лучшие пандарийские лекари из деревни Бинан. Похоже, они поправятся.$b$bПо дороге в Бинан тебе прийдется пройти по Сокрытой лестнице к вершине Кунь-Лай. Возьми это послание в Бинан, и отдай его в руки мэра Ежевичный Посох. У него и спросишь, где найти твоих друзей.$b$bНадеюсь, наши дороги еще пересекутся.$b$b-Хранитель истории Чо', 0),
(4514, 'ruRU', 'Создатель Разделения Темного и Светлого Эля и учения о Сбалансированном Опьянении.$b$bИзыскивая средство, смягчающее отрицательное воздействие пива и не влияющее на его положительные стороны, Цюань Тоу Ко изобрел двухчастную систему пития, созданную для достижения состояния сбалансированного опьянения. Употребляемые раздельно в надлежащих пропорциях Светлый Эль духа и Темный Эль разума объединяются в желудке выпившего, чтобы тот достиг состояния просветления и доброжелательности без помутнения рассудка и потери самоконтроля, привычных для любителей хмельного.', 0),
(4515, 'ruRU', 'Укрощенные лесные хозены, несмотря на то, что приняли культуру пандаренов, сохранили в глубине души склонность к простым радостям своего народа. Они любят охотиться и рыбачить, и могут атаковать любого, кто оказался в их охотничьих землях. Ситуация осложняется тем, что охотничьи земли хозенов редко имеют четко очерченные границы. К счастью, большинство хозенов находится под наблюдением пандарийских монахов.', 0),
(4518, 'ruRU', 'Янтарь – основа общества богомолов. На нем основаны их архитектура, искусство и технологии.$b$bБогомолы издавна славились мастерством управления звуком. Они нашли способ расширить диапазон слышимости с помощью янтарной смолы и теперь могут переговариваться на огромном расстоянии. Ни одна армия не могла подойти к землям богомолов незамеченной, и даже одинокие путники, пересекающие стену, находятся под пристальным наблюдением.$b$bИмператрица и Совет клакси бережно хранят великие деревья кипари из Танлунских степей, единственный источник драгоценного янтаря. Предание гласит, что некогда кипари можно было встретить и к востоку от стены, но могу вырезали их под корень, стремясь избавиться от всего, что связано с богомолами, их извечными врагами.', 0),
(4520, 'ruRU', 'В темные времена империи могу рабам-пандаренам не разрешалось иметь никакого оружия. Для своих тайных тренировок монахи обычно использовали земледельческие орудия или обычные бамбуковые палки, а также оттачивали мастерство боя без оружия.$b$bСамые популярные виду оружия могу были, напротив, скорее устрашающими, чем практичными: большие, громоздкие и неуклюжие. Преимущество монахов-пандаренов было в скорости перемещения и молниеносности ударов. Более крупные и медлительные могу нередко бывали совершенно дезориентированы скоростью монахов.$b$bС годами стиль боя пандаренов сильно изменился, вобрав в себя новые способности, стили, виды оружия. Но суть его осталась все той же: неважно, какого размера противник, просто победи его. Если понадобится – одними когтями.', 0),
(4521, 'ruRU', 'Император Лао-Фэ был настоящим чудовищем даже по меркам самих могу. Его излюбленной карой  рабов-пандаренов было разделение семей. Детей провинившихся отправляли на Змеиный Хребет, где их разрывали в клочья стаи богомолов.$b$bТакая участь постигла и юного пандаренского монаха по имени Кан. После того, как у него отняли любимого сына, он был убит горем и с тех пор облачался лишь в черные одеяния. Ему открылось прозрение, и он понял, насколько немощны владыки могу. Они владели темной магией создавали жуткое оружие, но империя их полностью зависела от труда рабов.', 0),
(4522, 'ruRU', 'Во времена правления могу покоренным народам не разрешалось иметь оружие, но Кан решил, что оно пандаренам и не нужно. Боевые искусства позволили пандаренским монахам самим стать оружием. Кана же нарекли Кулаком Первого Рассвета.$b$bНе сохранилось сведений о том, удалось ли Кану встретиться с сыном. Но истина остается неизменной: именно отеческая любовь явилась первой искрой восстания, изменившего лик Пандарии навечно.', 0),
(4528, 'ruRU', 'Яунголы, обреченные выживать на бесплодных землях Танлунских степей со времен последнего пандарийского императора, полностью изменили свой образ жизни.$b$bЭтот народ беспрерывно кочует, разбивая временные стоянки, "огненные стойбища", в местах, изобилующих природными ресурсами (особенно нефтью и дичью). Где разбить лагерь, сколько продлится стоянка и куда двигаться дальше, решает исключительно вождь.$b$bВ бою яунголы предпочитают атаковать быстро и яростно, используя конницу на флангах, чтобы давить на противника, пока тяжеловооруженная пехота атакует слабые места вражеского строя. Магия пламени и огнеметные осадные орудия прикрывают основные силы.$b$bЯунголы известны тем, что отступают так же быстро, как нападают, предугадывая действия врага, и используют все свои силы, только когда полностью уверены в победе.', 0),
(4530, 'ruRU', 'Вождем племени может стать только самый сильный, отважный и выносливый яунгол. Именно эти качества считаются среди них важнейшими, и обладать ими должен всякий вождь яунголов.$b$bОднако, учитывая постоянную угрозу, исходящую от богомолов, они не могут позволить себе потерять ни единого воина во внутренней борьбе за власть.$b$bПоэтому было принято на удивление цивилизованное решение. Когда у двух яунголов возникает конфликт, между ними ставится флаг, и противники бьются друг с другом затупленным оружием до тех пор, пока один из них не уступит или не потеряет сознание.$b$bПодобным образом выбирают и нового вождя: яунгол, желающий занять место предводителя, должен встать под флаг своего рода и драться со всяким, кто оспорит его право на лидерство.', 0),
(4535, 'ruRU', 'О происхождении яунголов мы знаем очень мало. Самые ранние записи в хрониках о яунголах датируются временами правления императора могу Цяна Безжалостного. Его ученые писали о кочевых племенах "разумных охотников-быков", которые странствовали по "обширным охотничьим угодьям за пределами западных границ империи."$b$bНекоторые племена яунголов не смогли покинуть Пандарию после Раскола, когда эта земля отделилась от большого континента.$b$bЗастряв в опасных Танлунских степях, как в ловушке, яунголы были вынуждены приспосабливаться, используя местные запасы нефти как оружие и развивая свою довольно агрессивную культуру.$b$bНемногие народы способны выстоять против богомолов в открытом бою. По одной лишь этой причине яунголов стоит уважать и бояться.', 0),
(4537, 'ruRU', 'На этом самом месте десять тысяч лет назад Шао Хао, последний император Пандарии, победил Ша Сомнения, заточив его под землей.$b$bОтрывок из Книги Бремени, глава 5:$b$b"Шао Хао медитировал три дня и три ночи, ибо совет, данный Нефритовой Змеей, казался ему туманным. Как можно самого себя избавить от всех сомнений?"$b$b"Устав от ожидания, спутник Шао Хао – король обезьян – вырезал из бамбука странную маску, на которой запечатлел гримасу сомнения. Он предложил императору спрятать под ней свое лицо..."$b$bНедобрыми были намерения короля обезьян, но все обернулось к лучшему: едва Шао Хао снял маску, как все его сомнения приняли телесную форму. Семь часов они бились друг с другом, пока император не победил Ша Сомнения.$b$bС этого дня последний император не сомневался в том, что сумеет спасти Пандарию от Раскола. Он обрел веру.', 0),
(4543, 'ruRU', 'Десять тысяч лет назад на этом самом месте Шао Хао, последний император Пандарии, просил совета у Нефритовой Змеи.$b$bОтрывок из Книги Бремени, Глава 3:$b$b"Всеми покинутый и лишившийся надежды, последний император ступил на крутой склон горы Неутомимых. Холод острыми кинжалами пронзал его шелковые одежды, а ветер, что неустанно дул в лицо, нашептывал, что путь его бесцелен."$b$b"Лишь на самой вершине горы обрел император покой и уединение, и говорил он там с Нефритовой Змеей, духом мудрости."$b$bИ был совет Нефритовой Змеи таков – освободиться от бремени, очистить свой дух и стать единым с этой землей.$b$bИмператора озадачили эти слова, но никаких иных ответов не открылось ему на вершине холодной горы. Удрученный, император Шао Хао спустился по склону вниз, дабы посоветоваться со своим спутником, Королем обезьян, и решить, что же делать дальше.', 0),
(4549, 'ruRU', 'На этом самом месте десять тысяч лет назад Шао Хао, последний император Пандарии, победил Ша Страха, заточив его в недра земли.$b$bОтрывок из Книги Бремени, глава 14:$b$b"Даже избавившись от сомнения и отчаяния, император Шао Хао не смог превозмочь свой страх. Он искал совета у Черного Быка, духа отваги и мужества, жившего в степях за стеной."$b$b"Черный Бык, Красный Журавль, император и король обезьян долго говорили о природе страха, пока, наконец, Король обезьян не решил, что пора действовать. Он сделал маску страха – любого, кто смотрел на нее, охватывал ужас. Дрожащими руками император надел кошмарную маску, и все его страхи вырвались наружу..."$b$bСемь дней и еще один день сражались друг с другом император и Ша Страха, и легенда гласит, что все это время солнце боялось взойти над землей. Одолев Ша и заточив его под землей, Шао Хао изменился навеки, ибо в нем больше не осталось страхов. Он обрел мужество.', 0),
(4559, 'ruRU', 'Орден шадо-панов был основан десять тысяч лет назад по приказу Шао Хао, последнего императора Пандарии.$b$bИмператор Шао Хао знал, что темная энергия ша – телесное воплощение таких чувств, как гнев, страх, ненависть или сомнение, представляет великую опасность для пандаренов, если позволить ей заразить эти земли. Он повелел величайшим воинам Пандарии сдерживать энергию ша и управлять ей.$b$bНа этом самом месте, всего через несколько часов после того, как Шао Хао превозмог собственные злость, ненависть и жестокость, первый из шадо-панов преклонил колено и принес присягу последнему императору. И с тех самых пор, на протяжении десяти тысяч лет, те же самые слова произносит каждый новобранец Шадо-Пан.', 0),
(4561, 'ruRU', 'На этом самом месте много веков назад стояла лавка Шень-Цзыня, которого так любили местные фермеры. Однажды первый пандарийский исследователь Лю Лан пришел к нему с весьма неожиданным списком покупок, который сохранился и по сей день:$b$b     Один фонарь$b$b     Три литра лампового масла$b$b     Четыре упаковки сушеных фруктов$b$b     Два мешка сушеных бобов$b$b     Четыре окорока солонины$b$b     Двенадцать литров пресной воды$b$b     Одна корзина сухарей$b$b     Один компас$b$b     Одна подзорная труба$b$bЛю Лан объявил, что собирается отправиться в путь, чтобы исследовать мир. Шэнь-Цзынь, посмеявшись над покупателем, предложил Лю Лану захватить с собой зонтик, и даже сказал, что не возьмет за него плату.$b$bПоклонившись, благодарный Лю Лан сказал Шэнь-Цзыню: "В твою честь я назову свою морскую черепаху!" И, довольный, ушел с полной тележкой покупок, насвистывая на ходу и ловя на себе любопытные взгляды.', 0),
(4562, 'ruRU', 'Много веков назад исследователь Лю Лан, каждые пять лет возвращался в Пандарию на спине гигантской морской черепахи и каждый раз забирал с собой все больше тех, кого манило неизведанное. Местные прозвали эту черепаху "Скитающимся островом", ибо она выросла настолько, что на спине ее уже построили небольшой город и даже возвели храм.$b$bОднажды местная вдова Маб Буйный Портер, горевавшая о погибшем на винодельне муже, объявила, что Пандарии больше ничем не сможет ее обрадовать. С этими словами она вместе со своим младшим сыном Ляо Буйным Портером взошла на спину черепахи, став первой среди поступивших так хмелеваров.$b$bСтранствующий Остров много веков не появлялся в Пандарии. Считается, что черепаха Шэнь-Цзынь Су перестала возвращаться туда после смерти своего возлюбленного друга Лю Лана.', 0),
(4565, 'ruRU', 'Создатель согревающего душу пива.$b$bЭтот напиток наполняет все тело теплом и спокойствием. Говорят, что Синь Во Инь так любил свои творения, что рыдал навзрыд, отдавая каждый бочонок пива.', 0),
(4601, 'ruRU', 'Непознанное – величайшее сокровище. И всякое белое пятно на карте – история, которую только предстоит рассказать. Лю Лан$b$bПервый пандарен-путешественник Лю Лан отправился в плавание с материка на спине великой черепахи Шэнь-Цзынь Су. Его открытия доказали, что остальной мир тоже пережил Разлом.$b$bОн возвращался в Пандарию каждые пять лет, увозя с собой все больше желающих путешествовать, и плавал до самой своей смерти, которая пришла нему, когда Лю Лану было 122 года. После его смерти Черепаха Шэнь-Цзынь Су так и не вернулась в Пандарию.', 0),
(4606, 'ruRU', 'Одному молодому крестьянину не повезло – он делил комнату на постоялом дворе со старым монахом, который от захода солнца до утренней зари без умолку рассуждал о философии и науке. Когда монаху наскучило вести монолог, он предложил крестьянину игру на сообразительность.$b$bКрестьянин не собирался состязаться в сообразительности с монахом, но тот все же придумал, как его заинтересовать: "За каждый твой вопрос, на который я не отвечу, ты получишь 50 золотых. А если ты не ответишь на мой вопрос, заплатишь мне 5 золотых."', 0),
(4607, 'ruRU', 'На эти условия крестьянин согласился.$b$b"Превосходно!" – воскликнул монах, и попытался придумать не слишком сложный, но и не особенно простой вопрос. "Как измерить объем тела неправильной формы?" спросил он с огоньком в глазах.$b$bДаже не пытаясь задуматься, крестьянин отдал монаху 5 золотых монет.$b$bМонах был разочарован, но собрался с мыслями, ожидая вопроса крестьянина.', 0),
(4611, 'ruRU', 'Однажды кровожадный властитель могу собрал армию и решил захватить Нефритовый лес.$b$b"Я восстановлю империю могу!" – заявил он, подойдя к вратам храма Нефритовой Змеи. "Вы снова станете покорными рабами!"$b$bСо стены донесся ответ пандарена-монаха: "Сколько могу ты привел, чтобы сразить нас?"$b$b"Со мной армия из сотни воинов могу!" – гордо сказал властитель.$b$b"Но за этими стенами пять сотен воинов пандаренов", – с уверенностью в голосе сообщил монах.$b$bВоины могу забеспокоились и усомнились в своем предводителе. Сомнения наполнили их сердца страхом, и армия разбежалась.', 0),
(4612, 'ruRU', 'Властитель был вне себя. Отступив от храма, он начал снова собирать союзников. После долгих споров, угроз, обещаний и увещеваний могу собрал новую армию.$b$bПодступив к вратам храма Нефритовой Змеи, властитель закричал: "Со мной шестьсот воинов могу, которые сотрут в порошок пять сотен жалких пандаренов."$b$bИ снова со стены донесся голос того же монаха: "А я уже говорил, что у каждого нашего монаха есть взрослый облачный змей? Они обожают мясо могу... и сейчас они очень голодны."$b$bВоины могу, испугавшись подобной участи, побежали прочь от стен храма.', 0),
(4613, 'ruRU', 'Ярости властителя не было предела. В третий раз он начал собирать свою армию. Он потратил на это много лет, но вернулся к стенам храма с могучим легионом цийлиней и могу с оружием из гробниц древних императоров.$b$b"На колени, ничтожества!" – прокричал он. "У ваших ворот тысяча могу и пять сотен цийлиней. У нас есть оружие и темная магия древних!"$b$bСо стены донесся ответ монаха: "А вы уже нашли нашего шпиона? Он очень хитрый и проворный."', 0),
(4614, 'ruRU', 'Воины легиона начали смотреть друг на друга со злобой. Каждый подозревал в другом шпиона и предателя. Могу неведомо доверие, они признают только грубую силу.$b$bУ храма началась битва. Могу сражались друг с другом до последнего, давая волю своей злобе, недоверию, страху, ненависти, жестокости и презрению.$b$bКогда битва закончилась, в живых у ворот остался лишь властитель. В этом бою он уничтожил многих своих союзников, оставшись без поддержки и без шансов на продолжение войны.', 0),
(4615, 'ruRU', 'Из храма вышел пандарен-монах, посмотрел на поле боя и начал наводить порядок.$b$b"Где твоя армия?" – спросил у него властитель.$b$b"Ты сам с ней пришел", – ответил монах и улыбнулся. "Друг мой, тот, кто отчаянно хочет нанести удар первым, заранее проиграл."', 0),
(4616, 'ruRU', 'Цзинь-юй сидел у реки и размышлял о вечном, когда к нему подошел саурок. Поначалу цзинь-юй встревожился и подумал, не нырнуть ли ему в реку, чтобы скрыться.$b$bНо саурок примирительно поднял лапы и сказал: "Я хочу переправиться на другой берег, но не умею плавать. А ты умеешь. Может, разрешишь мне переплыть реку на твоей спине?"$b$bНа это цзинь-юй ответил: "Но ты же меня укусишь, зарежешь или откусишь мне голову."', 0),
(4631, 'ruRU', 'Во время зандаларских войн, сразу после основания Империи пандаренов, маленькая Цзян гуляла по Дендрарию и услышала странные звуки. Она подошла поближе и увидела на земле умирающего облачного змея. С материнской нежностью юная Цзян взяла змея в руки и стала заботиться о нем. его к себе и выходила. Она назвала змея Ло, и они быстро стали друзьями.', 0),
(4632, 'ruRU', 'Окружающие не одобряли эту дружбу. Облачных змеев побаивались, их считали дикими и опасными существами. Цзян стали сторониться, ее уговаривали избавиться от Ло, пока тот еще не вырос во взрослого змея и не способен причинить ей вред.$b$bОднажды армия зандаларов продвинулась далеко на юг, достигла Нефритового леса и напала на Пандарию со стороны моря. Цзян не осталась в стороне и, взяв оружие, защищала свой народ.', 0),
(4633, 'ruRU', 'В одной из битв Цзян чуть было не лишилась жизни. За секунду до того, как копье должно было пронзить ее сердце, на помощь пришел Ло.$b$bЗмей, который тогда был еще очень юн, налетел на тролля и разорвал его на части. Затем он подхватил раненую Цзян и унес ее с поля боя.$b$bКогда Цзян поправилась, она обратилась к военачальникам Пандарии – бесстрашным воинам-монахам, которые защищали земли от нашествия троллей и других опасностей.', 0),
(4634, 'ruRU', 'Она попыталась объяснить, что змей может помочь им и изменить ход войны.$b$bНо ее не желали слушать. Монахи считали, что и без юной Цзян знают, как лучше, и решили продолжать действовать по своему плану.$b$bНо Цзян не сдалась. Наоборот, отказ придал ей решительности.', 0),
(4651, 'ruRU', 'Прошло несколько дней, и войска зандаларов высадились на побережье и начали наступление вглубь страны. Воители пандарены держали оборону на большом мосту у Цветущей Зари. Изо всех сил они пытались сдержать наступление, но преимущество было не на их стороне. Зандалары превосходили их числом и использовали летучих всадников, против которых у пандаренов не было оружия. Стало ясно, что надежды на победу нет.', 0),
(4652, 'ruRU', 'Но вдруг наблюдатели заметили что-то в небе! Это была Цзян верхом на своем друге Ло!$b$bВдвоем они ринулись в атаку, скидывали атакующих зандаларов с моста и сокрушали летучих всадников. Никто не смог противостоять ярости двух друзей.$b$bВойна продолжалась еще несколько месяцев, но эта битва стала в ней переломным моментом. Вскоре Цзян начала учить других пандаренов верховой езде на змеях.', 0),
(4653, 'ruRU', 'Цзян и Ло стали героями! С того самого дня змей считается у пандаренов символом надежды. Тогда же был основан Орден Облачного Змея. И по сей день они стоят на страже Нефритового леса.', 0),
(4657, 'ruRU', 'Саурок засмеялся: "Тогда мы оба погибнем. Без тебя я утону."$b$bЦзинь-юй обдумал слова саурока и согласился. С трудом тяжелый саурок вскарабкался на спину цзинь-юй, и они отплыли от берега.$b$bНо посреди реки саурок, не раздумывая, ударил цзинь-юй своими острыми когтями.$b$bТело цзинь-юй пошло ко дну. Вместе с ним утонул и саурок.$b$bДаже когда на кону стояла его жизнь, он не мог перебороть свою природу.', 0),
(4658, 'ruRU', 'Тот задумался и через некоторое время задал свой вопрос: "У кого сердце тигра, мудрость орла и сила быка?"$b$bМонах обрадовался новой пище для ума, вскочил на ноги и начал ходить по комнате. Шесть часов он хранил гробовое молчание, пытаясь разгадать загадку крестьянина. Постепенно его спокойствие превратилось в раздражительность, а раздражительность – в ярость и отчаяние. "Довольно! Я сдаюсь!" – закричал он, размахивая руками. Он достал кошель, нехотя отсчитал 50 золотых монет и отдал их сопернику, который с радостью принял свой выигрыш.', 0),
(4659, 'ruRU', 'Монах, не отрываясь, смотрел на соседа. "Ну! – не выдержал он. – Каков ответ на твою загадку?"$b$bКрестьянин молча отдал монаху 5 монет.', 0),
(4666, 'ruRU', 'День 12$b$bУважаемый Вождь-$b$bПосле гибели Крага в бою с флагманским кораблем Альянс я принял командование флотом на себя. Он погиб как герой и испустил свой последний вздох, только узнав о поражении Альянса.$b$bНаш флот понес тяжелые потери в этом бою, но один за одним наши поврежденные корабли победно пристают к берегам этой необычной земли. Ее нет ни на одной карте.$b$bЯ приказал батракам построить для нас безопасную гавань, где мы сможем заняться ремонтом.', 0),
(4667, 'ruRU', 'День 13$b$bТолстые создания, напоминающие медведей, называют эту землю своим домом. Это "пандарены". Далган говорит, что какой-то пандарен участвовал в основании Оргриммара, но Далган пьет не просыхая и врет напропалую.$b$bНе похоже, чтобы от этих пандаренов исходила угроза, но у них есть необходимые нам ресурсы: пища, дерево, камень... Если все это говорит о богатстве найденных нами земель, то хорошо бы Орде завладеть ими.', 0),
(4668, 'ruRU', 'День 14$b$bРазведчики обнаружили древние, пустынные руины у скалы, возвышающейся над бухтой. Это идеальное место для крепости. Не думаю, что в ближайшие недели нам стоит ожидать подкрепления из Оргриммара. Поэтому я взялся за древние манускрипты и отдал нашим чернокнижникам приказ начать призыв демонических сил для укрепления нашей армии. Такая демонстрация силы без сомнений устрашит пандаренов и заставит их присоединиться к нам.$b$bГлубокой ночью к берегу приплыл целый батальон отрекшихся, которые выжили в морской битве. Похоже, они не тонут. Вонь стоит страшная, но от них может быть польза.', 0),
(4669, 'ruRU', 'День 15$b$bИзвестия о нашей победе на море и открытии этих новых земель достигли Оргриммара. Не сомневаюсь, подкрепление уже в пути. Наши разведчики заметили корабли Альянса, плавающие среди обломков на месте морского сражения. Они наверняка вернутся. Мы будем к этому готовы.$b$bОт пандаренов никакого толка. То, чем мы готовы торговать, их не интересует. Даже при виде самых мощных артефактов они кривят свои черные носы. Моим солдатам нужна еда. Не можем же мы питаться телами утонувших матросов, как это делает нежить. Заносчивость пандаренов заставляет мою кровь просто бурдить от ярости. Я еле держу себя в руках.', 0),
(4670, 'ruRU', 'Ден 17$b$bАльянс уже близко. Я чувствую это. Не знаю, в чем причина, но я постоянно ощущаю нарастающие тревогу и страх. В этих землях есть что-то такое, что буквально высасывает из меня силы. Я приказал чернокнижникам призвать демонического наблюдателя, чтобы мы могли держать под контролем берега. Они настаивают на том, что мы не сможем контролировать его. В то время, когда мне так нужно поддержка, меня окружают трусы. Почему я так сильно сомневаюсь во всем? Клянусь, даже моя кожа теряет свой цвет.', 0),
(4671, 'ruRU', 'День 19$b$bПандарены прислали своего представителя, который попросил нас перестать рубить деревья. Я сказал ему, что им стоило бы прислушаться к моей просьбе снабдить нас древесиной, хорошенько вздул и отправил восвояси. Выплеснув свой гнев, я почувствовал себя гораздо лучше.$b$bАльянс скоро вернется, времени у меня все меньше. Я должен что-то придумать, чтобы пандарены прислушались к нам. Может, если завладеть чем-то, что для них ценно, то это продемонстрирует им нашу силу? К тому же, у нас появится повод для сделки. У Белландры была отличная идея – похитить их детенышей.', 0),
(4672, 'ruRU', 'День 21$b$bК югу от нас появился боевой корабль Альянса. Я отдал приказ всем занять боевые посты. Я лично буду руководить обороной лагеря Гаррош''ар.$b$bЯ чувствую, как внутри меня растет великая тьма. От пролития крови Альянса мне должно стать легче. Я готов.', 0),
(4928, 'ruRU', 'Общий уровень потерь союзников повысился до 64%. Нужны припасы.', 0),
(4929, 'ruRU', 'Получена большая партия Тревого-ботов. Они разобраны и переделаны в осколочные гранаты.', 0),
(4932, 'ruRU', 'Осознание военной угрозы и органическая реакция на нее распространяются среди роботов слишком быстро. Наземные боевые единицы, скорее всего, заражены. Необходимо разработать планы создания нового пульта управления "Блескотронами", чтобы удаленно вызывать роботов-ветеранов, которые могут вести разведку и уничтожать цели.', 0),
(4933, 'ruRU', 'Запасы подарков упали до неприемлемого уровня. Разрешен доступ к военному резерву.', 0),
(5141, 'ruRU', 'Да будет этот неудавшийся король навеки погребён в собственном трупе до конца времён.$b$BПусть имя его будет стёрто из памяти, а наследие сгниёт на корню.$b$bТакова судьба тех, кто посмел бросить вызов мистикам.', 0),
(5158, 'ruRU', 'Лифтбрул, величайший силач ("Нет, эту часть вычеркни!") среди всех дрогбаров, чемпион Тёмнокаменных.\n\nУвековечен в камне вождём Рыноксом, вторым по силе дрогбаром своего времени ("Что ты там пишешь, Резчик камня?").\n\nЭто не статуя, это Лифтбрул. Рынокс — Ваятель камня ("Там написано что-нибудь хорошее про меня?").', 0),
(5176, 'ruRU', '"Итак, меня окружила по меньшей мере сотня мурлоков!" - провозгласил мужчина с густыми усами и махнул в сторону широкой арки.\r\nРыжая тауренка издала возглас изумления. "А ты - что?" - в ее голосе звучали жесткие нотки.\r\n"Ну, а что мне оставалось, дорогая моя? - Маркус погладил клинок, свисающий с его бедра. - Я свершил над ними правосудие!"\r\n"Ого! У тебя был только этот кинжал? Ты такой храбрый!" Танда осторожно протянула руку к клинку, но в последний момент одернула ее.\r\nМаркус рассердился: "Что? Вообще-то это двуручный меч, и на нем чар по самую рукоять. Может, он и не такой большой, какие ты привыкла видеть, но я знаю несколько трюков, чтобы выжать из него все, на что он способен".\r\nТанда сдержанно улыбнулась, ее невероятно длинные ресницы затрепетали. Она взяла кусочек сыра и поднесла его к губам Маркуса.\r\n"Домашний. Попробуй".\r\nСтатный паладин растерянно пробормотал: "Н-нет. Я...э-э... не переношу лактозу".', 0),
(5181, 'ruRU', 'Лорд Грейвсбейн сидел в своей каюте и с тоской смотрел в иллюминатор. Свинцовые волны то вздымались, то опускались, и у него самого то ком подкатывал к горлу, то все словно обрывалось внутри. Сколько уже он прождал ее на своем роскошном корабле? Он чувствовал, как в нем поднимается желание; он уже сгорал от нетерпения.\n\nНаконец дверь каюты распахнулась. Она стояла в дверном проеме; на ней было полупрозрачное шелковое платье с глубоким декольте. Отблески света факелов играли на ее лице, подчеркивая утонченную бледность кожи син''дорай. "Я заставила вас ждать, мой повелитель?" – спросила она, слегка прикусив нижнюю губу.\n\nОн смотрел на эльфийку, словно завороженный; у него аж челюсть упала. Наконец он наклонился, поднял челюсть с пола и вставил на место.', 0),
(5183, 'ruRU', 'Его пудовый кулачище с хрустом врезался огру прямо в челюсть. Здоровяк зашатался, словно марионетка, у которой вдруг обрезали ниточки, и рухнул на своего брата, уложенного на землю минутой ранее. Братья Чернозубы наводили ужас на всю округу, но куда им было тягаться с доблестным сэром Криспином Седогривом!$B\r\nОднако храброму герою некогда было наслаждаться зрелищем поверженного врага – нужно было скорее освободить прикованную к стене леди Лунный Сумрак! С грацией горного барана Дун Морога Седогрив приблизился к пленнице. "Вы не ранены, моя госпожа? Надеюсь, эти мерзавцы не тронули вас?"\r\n', 0),
(5184, 'ruRU', '<HTML>\n<BODY>\nСкабрезный любовный роман C\n<IMG src="Interface\\Pictures\\SteamyRomance10" width="301" height="354" texCoordRight="0.58984375" texCoordBottom="0.69140625"/>\n</BODY>\n</HTML>', 0),
(5185, 'ruRU', 'Смущенно потупив глаза, она приняла из его рук кубок с вином. "Право, не знаю, лорд Грейвсбейн. Моя мама наверняка была бы против".\n\n"Полно, дорогая моя Элония, – возразил ей лорд, – тебе уже десять тысяч лет, и ты давно не ребенок. Думаю, твоя мать ничего не будет иметь против, если ты позволишь себе глоток вина".\n\nОна хихикнула. "Да дело не в вине, мой повелитель. Скорее, меня смущает то, что я, дитя ночи, провожу вечер в компании..."\n\n"Очаровательного собеседника?" – предположил он.\n\n"Скорее, старой развалины".', 0),
(5196, 'ruRU', '"Некоторые вещи стоят того, чтобы ждать, леди Солнечная Кожа". Он протянул к ней руку, маня к себе. \n\nНа секунду она заколебалась; дыхание ее было неровным, и неуверенность боролась с желанием. Затем она нежно коснулась своими изящными пальчиками его холодной, мертвенно-бледной щеки. "Надеюсь, в вас еще осталось достаточно жизни, лорд Грейвсбейн?"\n\nОн взял ее руку в свою и поцеловал. "Не бойся, дорогая. Хоть челюсть моя держится в суставах уже не столь крепко, зато мой язык проворен, как в юности".', 0),
(5197, 'ruRU', 'Она облегченно вздохнула, когда спаситель снял оковы с ее запястий и лодыжек. "Только благодаря вашему своевременному вмешательству, мой доблестный защитник", – ответила она. Сияющие глаза ночной эльфийки смотрели на него, словно яркие звезды в безлунную ночь. "Невыносимее всего для меня было ощущать на себе их похотливые взгляды. Мои доспехи немного порвались, когда они схватили меня... что-то и совсем отвалилось". Она сделала неловкую попытку прикрыть свою обнаженную осиную талию.$B\r\n "Не беспокойтесь, сударыня, – благородный рыцарь, конечно же, не обратит внимания на подобный казус", – заверил он, предложив ей руку, чтобы помочь подняться на ноги.\r\n', 0),
(5198, 'ruRU', 'Выпрямившись в полный рост, леди Лунный Сумрак оказалась на добрых три головы выше своего спасителя. Она озадаченно посмотрела на него. "Простите мне мое любопытство, добрый господин, но я никак не разберу – вы самый маленький из людей или самый высокий из дворфов?"$B\r\n Он улыбнулся во весь рот, обнажив ослепительно-белые зубы. "Мне приятно думать, что я перенял лучшее и от тех, и от других, моя госпожа". Он кивнул в сторону двери. "Нас ждет просторная карета, которая доставит вас домой. Заверяю вас, мой кучер не побеспокоит нас во время нашего путешествия. Я сделаю все возможное, чтобы скрасить вам долгую дорогу".\r\n', 0),
(5199, 'ruRU', 'Седовласый, но по-мужски еще привлекательный рыцарь отвесил даме легкий поклон и подмигнул. "Дорогуша, этого я буду ожидать с нетерпением!"$B"Ах, сэр Седогрив!" – воскликнула она, падая в его объятия. Он повел ее к ожидавшей их карете, по пути перешагнув через огров, лежавших без сознания на полу.\r\n $B$B <История продолжается с подробнейшим описанием приключений парочки в карете.>', 0),
(5200, 'ruRU', '"У меня все в порядке и с честью, и с совестью, могу вас заверить, – ответил он, сверля ее взглядом своего единственного зрячего глаза, – полагаю, ваша матушка будет от меня в совершенном восторге".\n\n"В самом деле?" – раздался резкий голос. Криспин Грейвсбейн обернулся и увидел в дверном проеме еще одну рожденную в ночи. Ее одежда была менее располагающей к фривольностям, но в остальном она была точной копией Элонии – те же черты лица, та же точеная фигура.\n\nОн встал и поклонился ей, торопливо пнув под диван отвалившуюся коленную чашечку. "Лорд Криспин Грейвсбейн, к вашим услугам. Я имею удовольствие видеть леди Марину?"\n\n"Ее самую", – холодно ответила она, окинув Элонию строгим осуждающим взглядом.', 0),
(5201, 'ruRU', '"Да нет же, госпожа, вы наверняка разыгрываете меня, – улыбнулся он ей лишь уголками губ, стараясь не выронить снова свою вставную челюсть, – конечно же, вы не мать Элонии, а ее сестра".\n\nЩеки леди Марины покрылись легким румянцем. "Вы мне льстите, мой лорд, – ее голос сразу смягчился, – уже много столетий нас с Элонией никто не принимал за сестер".\n\n"Вздор!" – решительно возразил он, беря ее под руку и ведя к дивану. Он усадил ее и сел сам между двух прекрасных эльфиек с кожей цвета индиго. "Давайте все вместе выпьем вина и узнаем, что еще есть общего у двух столь прекрасных дам".', 0),
(5210, 'ruRU', 'В честь тех, кто поднялся на немыслимые высоты. Пусть ваш дух продолжит жить в мечтах тех, кто последует за вами...', 0),
(5260, 'ruRU', '- НЕ ВХОДИТЬ -\n\nВ этом районе были замечены агенты Легиона.\n\nПожалуйста, немедленно сообщайте о любой подозрительной активности стражу Альтурасу в Аметистовой цитадели.', 0),
(5280, 'ruRU', '"Ах, лорд Грейвсбейн!" – воскликнула она и упала без чувств прямо в его объятия. Подводя ее к кожаному ошейнику, висевшему над кроватью, он вдруг осознал, что невольно наслаждается теплом ее кожи... \n\n<История, изобилующая скабрезными шуточками про "амбразуру", продолжается еще много глав...>', 0),
(5281, 'ruRU', '"Ах, лорд Грейвсбейн!" вспыхнула Марина. Она взяла руку Элонии в свою, обменявшись с дочерью лукавой улыбкой. "Пожалуй, пришло время посвятить вас в настоящие тайны шал''дорай".\n\n<Следующие страницы, текст которых сплошь замаран, похоже, изобилуют отборной эльфийской похабщиной.>', 0),
(5308, 'ruRU', 'НЕПОКОРНОСТЬ ФАРОНДИСА\n\nДоговор королевы Азшары с повелителем демонов Саргерасом почти не встретил сопротивления среди её подданных. Одним из немногих, кто осмелился бросить ей вызов, был принц Фарондис.\n\nБудучи одним из доверенных советников королевы, Фарондис регулярно общался с Высокородными Зин-Ашари, но его дворец в Азсуне находился в нескольких лигах от эльфийской столицы. Благодаря этому он смог наблюдать за влиянием Саргераса на двор Высокородных, не поддавшись соблазнам демонов.', 0),
(5309, 'ruRU', 'ГНЕВ КОРОЛЕВЫ\n\nПлан Фарондиса был смелым, но простым: уничтожить Колодец Вечности в Зин-Ашари. Это закрыло бы портал во владения Саргераса и остановило бы волну зла ещё до её начала. Чтобы выполнить эту задачу, он собирался использовать силу артефакта, хранившегося глубоко в академии Нар''талас: Камня приливов Голганнета.\n\nК несчастью, влияние королевы во дворце Фарондиса уже укоренилось глубоко. Вандрос, молодой дворянин из свиты Фарондиса, узнал о его планах бросить вызов королеве и донёс о заговоре самой королеве Азшаре.', 0),
(5310, 'ruRU', 'СУДЬБА АЗСУНЫ\n\nАзшара не теряла времени и покарала Фарондиса и его народ. В пугающей демонстрации чародейской силы она уничтожила Камень приливов Голганнета, тем самым выпустив волну тёмной энергии над всей Азсуной и её жителями.\n\nС того дня эльфы Азсуны не способны обрести освобождение смерти. Их духи — наши духи — бесконечно скитаются по этим землям... и всё из-за неразумной верности нашего принца.', 0),
(5332, 'ruRU', 'Здесь покоятся Верные Зову. $b$bОтважная Аэлинн и благородный Банлорус властвовали как на полях битв, так и при дворе. Они погибли так же, как жили — защищая наш народ от угроз со всех сторон.$b$bАну Дора. Мы помним.', 0),
(5333, 'ruRU', 'Здесь покоится Дорендил Дикий Зов.$b$bЕго звала к себе как природа, так и общество, и он был одним из первых, кто заговорил с гиппогрифами. Его наследие живёт в нашем вечном родстве с ними.$b$bАну Дора. Мы помним.', 0),
(5334, 'ruRU', 'Здесь покоится Лилиана Лугоклинок.$b$bЕё клинок не знал равных и скользил среди врагов, словно травинка танцует на ветру.$b$bАну Дора. Мы помним.', 0),
(5335, 'ruRU', 'Здесь покоятся Ветроборцы.$b$bСтрелки без равных, их мастерство владения луком стало вдохновением для поколений лучников.$b$bИх семья создала перчатки, которые носят часовые — искусно сочленённые кольчужные звенья, что по сей день усиливают наших лучников.$b$bАну Дора. Мы помним.', 0),
(5336, 'ruRU', 'Колокольчики Луны$b$bСёстры говорят, что Элуна поёт песню, чистую и прекрасную в каждой ноте.$b$bКолокольчик звонит нечасто, но когда это происходит, звучит та же нота, что поёт Она.$b$bЗин-ал Элуна.', 0),
(5337, 'ruRU', 'Здесь покоится Латара Перосвет.$b$bОхотница часовых, она вела авангард во многих походах. Её отвага и сострадание были безграничны.$b$bАну Дора. Я помню.', 0),
(5411, 'ruRU', 'Я — Иллисанна, дочь командира Сопротивления Курталоса Вороньей Скалы. Теперь вы уже должны знать, что мой отец мёртв. Я не единственная, кто кого-то потерял. Наша великая империя, весь наш мир горит перед нашими глазами.\n\nНичто в этой войне с Пылающим Легионом не идёт по плану. Ничто. За каждой выигранной битвой следуют два поражения. На месте каждого убитого демона появляется ещё десять.\n\nКак и мой отец, я когда-то была так уверена в победе. Так самонадеянна. Так глупа. Большинство бойцов Сопротивления до сих пор таковы. Они крепко держатся за свои архаичные методы, не желая признать, что мы не можем победить нашего врага обычными средствами. Мы сражаемся с чем-то чуждым этому миру, с чем-то, рождённым из кошмара.\n\nЕсть один эльф, который понимает это: Иллидан Штормгнев. Он знает, что для победы над демонами мы должны меняться. Мы должны принять необычные новые тактики. Если нет — мы погибнем. Всё очень просто.', 0),
(5788, 'ruRU', '<HTML><BODY>\n<H1 align="center">Том древних</H1>\n<IMG src="Interface\\Common\\spacer" align="center" width="1" height="27"/>\n<IMG src="Interface\\Pictures\\artifactbook-druid-cover" align="center" width="230" height="230"/>\n<IMG src="Interface\\Common\\spacer" align="center" width="1" height="27"/>\n<p align="center">Записано Селадайн, главным историком Ткачей Снов.</p>\n</BODY></HTML>', 0),
(6287, 'ruRU', 'ЕЖЕДНЕВНАЯ ДЕМОНСТРАЦИЯ КОРМЛЕНИЯ$b$bСпросите у любого из наших сотрудников о времени кормления и о том, как пройти в наш магазин подарков!$b$bЗНАЕТЕ ЛИ ВЫ? Морские львы-тюлени получили своё название благодаря грозному рыку, похожему на рык обычного наземного льва. Мы полагаем, что неволя сделала их застенчивыми, поэтому они больше не рычат.$b$bВот почему усилия по сохранению природы так важны. Ваше небольшое пожертвование Зверинцу поможет нам расширить экспозиции на тысячелетия вперёд!', 0),
(6290, 'ruRU', 'Танда положила сыр обратно в чашку. "О, ты уверен? Так значит, ты меня терпеть не можешь?" Громадная таурен шагнула вперед, прижав Маркуса к стене. Из-за солидной разницы в росте его лицо уперлось прямо ей в грудь. Она полностью перекрыла ему обзор, и он, пытаясь вырваться, обхватил ее рукой за спину. Его невнятные извинения только рассмешили ее, и она прижала бедолагу еще сильнее.\r\nДругой рукой он ухватил ее за хвост, и в этот момент в комнате стало заметно темнее: в дверном проеме появилась еще одна массивная фигура. "Что за..."\r\nТандра вскрикнула: "Бакс, нет!"\r\nМаркус высвободил голову и судорожно вдохнул, увидев разгневанного таурена с широко раскрытыми от удивления глазами. "Это не то, что ты подумал!"\r\nБакс рванулся вперед, прямо на Маркуса, на ходу проревев: "Связался с быком, бойся рогов!"\r\n', 0),
(6291, 'ruRU', 'Маркус чуть было не потерял равновесие, но быстро собрался с духом и принял боевую стойку. Он схватил таурена за рога обеими руками и что есть силы потянул вниз. Сделать это было непросто, все-таки Бакс - очень серьезный противник. Бакс сумел лишь на секунду поднять голову, чтобы издать гневный рык и сплюнуть на землю, но потом Маркус сделал усилие и снова заставил таурена опустить голову. На мгновение соперники встретились взглядом, и, сделав резкий рывок, Бакс все-таки освободился.\r\nТаурен раскинул руки, чтобы обхватить противника и сбить с ног, но внезапно... "Клинки Света!" - раздался рык паладина. Огромный сияющий меч буквально вырос из земли между двумя соперниками. Они стояли так близко друг к другу, что лезвие прошло в миллиметре от кожи, порезав одежду на груди человека и сбрив полосу шерсти на торсе таурена.\r\nПрежде чем противники могли продолжать, Танда ударила в землю копытом с воинственной яростью. Человек и таурен оказались в полном замешательстве. "Эй вы, хватит!"', 0),
(6292, 'ruRU', 'К Маркусу быстро вернулось самообладание. Он взглянул сначала на Танду, а потом на Бакса. Их шерсть вздыбилась, а открытые участки кожи блестели от пота. Все трое сверлили друг друга гневным взором. И тут Маркус, который, не смотря ни на что, выглядел ужасно соблазнительно, сказал: "Ну, раз мы и так уже почти раздеты..."$B\r\n<Ваш хороший вкус не позволяет вам читать дальше.>', 0)
